(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-sparse-dyn-attn"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-1\">一 · 一次线上事故：全注意力在长视频上撞上的墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-2\">二 · 它解决的问题：按运动显著性裁剪 token 对</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-3\">三 · 它不解决什么：三条明确的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-4\">四 · 适用边界的判定：什么时候值得开</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-5\">五 · 一个具体例子：把事故请求跑一遍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-6\">六 · 工程判断：先量折损，再定稀疏度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-7\">七 · 当“省下来的算力”变成画面上的闪烁：边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-8\">八 · 运动能量估计：代理路径的输入、输出与摊销代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-9\">九 · Top-K 选择与掩码构建：排序的代价与分块的对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-10\">十 · 掩码内 QK^T 与 PV：稀疏算子的实际吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-11\">十一 · 掩码跨步复用：运动连续性的假设与刷新代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-12\">十二 · 稠密残差相加：数值稳定与显存带宽的最后一跳</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-13\">十三 · 边界、失效条件与系统代价：稀疏掩码在 Blackwell 上的真实收益账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-14\">十四 · 从运动能量到掩码：显著性估计的可实现形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-15\">十五 · TopK 掩码的构造与稀疏度定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-16\">十六 · 稀疏注意力的逐项展开与残差路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-17\">十七 · 掩码复用的时间连续性假设与刷新策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-18\">十八 · 落到可实现：伪代码与分块约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-19\">十九 · 稀疏度、加速比与容量规划的三方约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-20\">二十 · 掩码落地时的分块代价与漏检边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-21\">二十一 · 请求形态：固定分辨率长视频才是主战场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-22\">二十二 · 长度分布：帧数增长改变的是显存与带宽，不只是 FLOPs</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-23\">二十三 · 并发与批大小：1–4 的批是显存约束下的产物</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-24\">二十四 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-25\">二十五 · 配方与硬件的对齐：Blackwell 档位上的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-26\">二十六 · 配方的边界条件与路由判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-27\">二十七 · 运动稀疏注意力的负载边界：何时收益兑现，何时反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-28\">二十八 · 硬件档位：从单卡到 NVL72 的取舍线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-29\">二十九 · 并行拓扑：掩码对齐先于切分策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-30\">三十 · 量化方案：稀疏路径与残差路径分开定精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-31\">三十一 · KV 策略：QKV 缓存随帧数与分辨率增长</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-32\">三十二 · 调度参数：稀疏度阈值与掩码复用窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-33\">三十三 · 可复现配置思路：从掩码对齐倒推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-34\">三十四 · 稀疏掩码与张量核心分块的对撞：理论加速比在哪里蒸发</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-35\">三十五 · 显存与带宽：QKV 缓存随帧数分辨率线性膨胀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-36\">三十六 · 代理估计的固定开销与掩码复用的摊薄边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-37\">三十七 · 通信：稀疏掩码在张量并行下的跨卡不一致</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-38\">三十八 · 功耗与规模崩塌的先后次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-39\">三十九 · 把系统代价折进掩码设计：一个可操作的判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-40\">四十 · 精度塌陷：残差路径掩盖的数值病</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-41\">四十一 · 显存与 OOM：稀疏不等于省显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-42\">四十二 · 批抖动与路由不均：稀疏度的方差问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-43\">四十三 · 尾延迟尖刺：掩码刷新与运动突变</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-44\">四十四 · 监控面与回滚：把稀疏当可降级特性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-45\">四十五 · 当稀疏掩码撞上张量核心：四类失效与可回滚的监控面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-46\">四十六 · 对照维度：稀疏发生在哪一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-47\">四十七 · 决策表：四类负载的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-48\">四十八 · 与缓存级复用的组合判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-49\">四十九 · 与精度级稀疏的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-50\">五十 · 适用条件的硬边界与规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-51\">五十一 · 选型的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-sparse-dyn-attn-sec-52\">五十二 · 选型边界：动态稀疏掩码与相邻方案的取舍判据</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:496px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 496.4 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"414.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">下采样潜变量或用轻量代理网络估计每token的运动能量</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"414.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按能量排序选top-k token构建稀疏注意力掩码</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"414.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">仅对掩码内token对计算QK^T与PV，其余token输出置零或走捷径</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"414.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">掩码按帧间运动连续性在相邻步复用，减少重复估计</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"414.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">稀疏结果与稠密残差路径相加保持数值稳定</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-sparse-dyn-attn-sec-1\">一 · 一次线上事故：全注意力在长视频上撞上的墙</h3>\n<p>某条面向长视频生成的扩散推理服务在扩容后出现了典型的“容量幻觉”：单请求的端到端时延在短片段上完全达标，但一旦请求分辨率提升、帧数拉长，P99 时延呈非线性抬升，批大小被迫从 4 压到 2 再压到 1，吞吐塌陷，SLO 违约集中在长请求上。事后定位并不复杂：瓶颈不在 VAE 解码、不在调度器、也不在权重带宽，而在时空注意力本身。视频扩散的注意力对全部帧对做全连接，序列长度随帧数与分辨率平方级膨胀，而画面中真正发生运动的区域只占少数 token——大量帧对之间的注意力权重接近于零，却仍然被完整地送进 QK^T 与 PV 的矩阵乘里。这就是全注意力在长视频上的算力浪费：FLOPs 按 N² 付费，有效信息却只落在少数 token 对上。</p>\n<p>这类事故的工程特征值得记录：它不是“慢一点”，而是“批大小掉档”。当注意力成为主导项，单请求显存与算力占用上升，连续批处理无法再靠堆批摊薄权重读取，GPU 的 SM 占用率被拖到低位，端到端时延与吞吐同时恶化。此时再调调度策略、再优化 KV 排布都收效有限，因为问题在算子级的计算量上。动态稀疏时空注意力正是针对这一层：它不改变模型权重，不改变采样器，只在注意力算子内部决定“哪些 token 对值得算”。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-2\">二 · 它解决的问题：按运动显著性裁剪 token 对</h3>\n<p>算法的核心判断是：视频 token 的运动能量分布高度不均。用低分辨率潜变量或轻量代理网络估计每个 token 的运动能量，可以写成 $e_i=\\|\\nabla_t z_i\\|$ 或代理网络的直接输出；按能量排序取 top-k 得到显著 token 集合 $\\mathrm{TopK}(e)$，再据此构建掩码 $M_{ij}=\\mathbb{1}[i\\in\\mathrm{TopK}(e)\\ \\text{且}\\ j\\in\\mathrm{TopK}(e)]$。注意力只在掩码内计算：$O_i=\\sum_j M_{ij}\\,\\mathrm{softmax}(Q_iK_j^{\\top}/\\sqrt{d})V_j$，掩码外的 token 对输出置零或走捷径。于是计算量从全连接的 $N^2$ 收缩到 $\\sum_i|\\mathcal{S}_i|$，稀疏度定义为 $\\text{sparsity}=1-\\frac{\\sum_i|\\mathcal{S}_i|}{N^2}$，注意力 FLOPs 随稀疏度线性下降。</p>\n<div class=\"formula\">$$\\text{Attn}(Q,K,V)_{i}=\\sum_{j\\in\\mathcal{S}_{i}}\\text{softmax}(s_{ij})V_{j},\\quad \\text{FLOPs}\\propto\\sum_{i}|\\mathcal{S}_{i}|,\\quad \\text{sparsity}=1-\\frac{\\sum_i|\\mathcal{S}_i|}{N^2}$$</div>\n<p>数据流顺序决定了它的工程形态：先估计能量，再排序选 top-k 建掩码，再只对掩码内 token 对算 QK^T 与 PV，然后按帧间运动连续性在相邻去噪步复用掩码以减少重复估计，最后把稀疏结果与稠密残差路径相加，$\\tilde O_i=O_i+R_i$，以维持数值稳定。注意最后一步不是装饰：纯稀疏输出会让未被选中的 token 失去注意力通路，残差路径保证这些位置仍有稠密信号兜底，避免训练-推理分布偏移被放大成画面崩坏。</p>\n<p>与固定稀疏模式的差别必须说清：局部窗口或固定步长稀疏按位置裁剪，与画面内容无关；本算法按运动能量动态选 top-k，掩码随内容漂移。与全注意力相比它降低 FLOPs，但保留稠密残差；与缓存级复用（跨步复用 K/V）不同，它属于注意力算子级稀疏，作用点是 QK^T 与 PV 的计算图，而不是缓存本身。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-3\">三 · 它不解决什么：三条明确的边界</h3>\n<p>第一，它不解决规则分块被破坏带来的加速折损。稀疏掩码是数据相关的、不规则的，而 Blackwell 上的 tcgen05 MMA 与 TMEM 路径依赖规则的分块形状才能喂满张量核心。掩码一旦打散 token 对的连续性，内核要么退化为按掩码逐块发射，要么在规则块内做零填充——两条路都让实际加速比低于理论稀疏度。在分块要求严格的档位上，这种折损会把收益大幅压缩，甚至出现“稀疏了但没快”的反常现象。这是算子级稀疏的固有代价，不是调参能消掉的。</p>\n<p>第二，它不解决显著性估计的漏检。代理估计基于低分辨率或光流，对快速运动、遮挡边界、突然入画的对象天然迟钝。漏检的直接后果是局部细节丢失与闪烁：运动物体边缘模糊、遮挡处纹理跳变。稀疏度越高，漏检的代价越被放大，因为被跳过的 token 对没有任何补救通路——残差只能兜住数值稳定，兜不住信息缺失。</p>\n<p>第三，它不解决掩码复用与运动突变之间的矛盾。按帧间运动连续性在相邻步复用掩码能摊薄代理估计开销，但若运动方向突变而掩码未及时刷新，稀疏注意力会持续跳过新出现的显著区域，画面局部停滞。复用窗口越长，估计开销越低，突变响应越差；这是一个必须显式配置的权衡，而不是自适应就能自动解决的问题。</p>\n<p>此外，它不改变显存随帧数与分辨率增长的基本事实：QKV 缓存仍按序列长度线性占用，稀疏只削减计算，不削减驻留。规模上限因此受显存与带宽约束，长视频高分辨率请求仍会先撞显存墙。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-4\">四 · 适用边界的判定：什么时候值得开</h3>\n<p>适用性可以按三个条件筛。其一是运动稀疏性：画面中显著运动区域占比低、背景大面积静止或缓慢漂移，稀疏度才有上升空间，收益随稀疏度上升。其二是分辨率与帧数：短片段、低分辨率下注意力本就不是主导项，开稀疏的代理估计开销与内核折损会吃掉收益，属于负优化区间。其三是 SLO 形态：以端到端时延为主的长视频生成请求最匹配，因为稀疏直接削减的是注意力时延；若 SLO 由首帧时延或解码阶段主导，稀疏注意力的贡献被稀释。</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>判定</th><th>主要代价来源</th></tr></thead><tbody><tr><td>长视频、高分辨率、运动区域稀疏</td><td>优先启用，收益随稀疏度上升</td><td>代理估计开销（可被掩码复用摊薄）</td></tr><tr><td>快速运动、大量遮挡与入画</td><td>慎用或降低稀疏度</td><td>漏检导致细节丢失与闪烁</td></tr><tr><td>规则分块要求严格的档位</td><td>收益被折损压缩，需实测</td><td>掩码破坏张量核心规则分块</td></tr><tr><td>短片段、低分辨率</td><td>不启用</td><td>代理开销与内核折损超过节省</td></tr></tbody></table>\n<p>部署侧的配方相对固定：Blackwell GPU 上以单卡或单节点张量并行为主，量化可配合 FP8/NVFP4，稀疏所需的 QKV 缓存随帧数与分辨率增长；批大小按显存档位取 1–4，SLO 以端到端时延为主。掩码复用是这套配方里最值得调的旋钮：复用窗口拉长，代理估计开销被摊薄，但突变响应变差；窗口缩短，响应变好，开销回升。工程上应把复用窗口与画面运动强度的在线统计绑定，而不是全局固定。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-5\">五 · 一个具体例子：把事故请求跑一遍</h3>\n<p>取那条事故中的长视频高分辨率请求：固定分辨率、帧数拉长、批大小因显存只能取 1。全注意力路径下，时空注意力的 FLOPs 按 N² 增长，单步注意力耗时压过 VAE 与调度开销，端到端时延随帧数非线性抬升，P99 违约。切到动态稀疏路径后，第一步用下采样潜变量估计每 token 运动能量，排序取 top-k 建掩码；后续去噪步按运动连续性复用掩码，代理估计只在窗口到期或运动统计突变时重跑；掩码内 token 对走 QK^T 与 PV，掩码外走捷径，输出与稠密残差相加。理论上注意力 FLOPs 随稀疏度线性下降，长视频高分辨率下时延显著降低。</p>\n<p>但实测不会等于理论。掩码不规则，内核在规则分块上做零填充，实际加速比低于稀疏度对应的理论值；若该请求包含快速运动的物体，漏检会让边缘细节丢失，表现为闪烁。此时正确的工程动作不是继续拉高稀疏度，而是收紧 top-k、缩短掩码复用窗口，用少量时延换回细节；或者对高运动帧段局部回退到稠密注意力。这正是适用边界的操作化：稀疏度不是越大越好，它是与画面运动统计、内核分块效率、SLO 余量三者共同约束下的一个工作点。</p>\n<p>容量规划上，这条请求的显存占用仍随帧数与分辨率增长，稀疏不减少 QKV 驻留，因此批大小仍受显存档位限制；收益体现在单请求时延与单位时间内可完成的请求数上，而不是显存。把稀疏当成显存优化手段是常见的误配，它削减的是计算图里的乘加，不是缓存里的字节。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-6\">六 · 工程判断：先量折损，再定稀疏度</h3>\n<p>落地时的第一个动作不是调稀疏度，而是量折损：在同一请求形态下对比理论稀疏度与实际注意力耗时下降比例，得到该档位的内核效率系数。这个系数由掩码不规则程度与分块形状共同决定，随稀疏度上升往往恶化——稀疏度越高，掩码越碎，零填充浪费越大。第二个动作是量漏检：用运动强度统计把请求分段，观察高运动段的细节指标与闪烁投诉，确定 top-k 的下限。第三个动作才是定复用窗口，把代理估计开销摊薄到可接受的水平，同时保证突变响应不超过一帧的容忍度。</p>\n<p>这三步的顺序不能颠倒。先追稀疏度会得到一个纸面漂亮、线上闪烁的工作点；先量折损则能判断该档位是否根本不值得开稀疏——在规则分块要求严格的档位上，折损可能吃掉全部收益，此时正确的判断是回退到稠密路径或改用其他手段，而不是继续在掩码形状上做微调。动态稀疏时空注意力的价值在于把“算哪里”从固定位置变成内容驱动，但它的收益上限由内核分块效率与显著性估计精度共同封顶，这两个量必须在容量规划阶段就被测出来，写进该请求形态的部署配方里。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-7\">七 · 当“省下来的算力”变成画面上的闪烁：边界与失效条件</h3>\n<p>线上事故的典型形态不是崩溃，而是“指标好看、画面难看”。某条长视频高分辨率生成请求在批大小取 1–4 的显存档位下跑端到端时延 SLO，注意力 FLOPs 随稀疏度线性下降、时延确实下来了，但审核侧发现运动物体边缘周期性模糊、遮挡处纹理跳变。根因不在算子本身，而在显著性估计：代理网络漏检了快速运动与遮挡区域，这些 token 的能量 $e_i=\\|\\nabla_t z_i\\|$ 被低估，落不进 $\\mathrm{TopK}(e)$，掩码 $M_{ij}=\\mathbb{1}[i\\in\\mathrm{TopK}(e)\\ \\text{且}\\ j\\in\\mathrm{TopK}(e)]$ 把它们整段跳过，输出只剩稠密残差路径 $R_i$ 兜底，于是 $\\tilde O_i=O_i+R_i$ 在数值上稳定、在语义上塌陷。更隐蔽的是掩码复用：按帧间运动连续性在相邻步复用掩码本意是摊薄代理估计开销，一旦运动方向突变而掩码未及时刷新，稀疏注意力会持续跳过新显著区域，画面局部停滞——这类故障不会触发任何显存或带宽告警。</p>\n<p>第二类代价来自硬件形态而非算法语义。稀疏掩码破坏张量核心的规则分块，tcgen05 的 MMA 与 TMEM 数据通路按固定 tile 取数，掩码内 token 对在块内分布零散时，实际加速比常低于理论稀疏度，在规则分块要求严格的档位上收益被大幅压缩。因此容量规划不能拿 $\\text{sparsity}=1-\\sum_i|\\mathcal{S}_i|/N^2$ 直接折算时延，必须按“有效分块密度”打折；显存侧同样如此，QKV 缓存随帧数与分辨率增长，稀疏只减算力不减驻留，长视频下带宽仍是硬约束。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>收益</th><th>风险</th></tr></thead><tbody><tr><td>运动区域稀疏、帧间连续</td><td>FLOPs 随稀疏度线性下降</td><td>低</td></tr><tr><td>快速运动/遮挡密集</td><td>加速比被分块碎片吃掉</td><td>细节丢失、闪烁</td></tr><tr><td>运动方向突变</td><td>掩码复用摊薄估计开销</td><td>新显著区域被持续跳过</td></tr></tbody></table>\n<p>适用边界因此可以写死：它解决的是长视频高分辨率、运动区域稀疏场景下全连接帧对注意力的算力浪费，属于注意力算子级稀疏，不做缓存级复用；它不解决 KV 驻留随帧数增长带来的显存与带宽压力，也不解决代理估计本身的漏检。工程判断是：把掩码刷新周期与运动突变检测绑定，对漏检区域保留一条低分辨率稠密旁路，并接受实际加速比低于理论稀疏度这一事实去做 SLO 预算。</p>\n<h3 id=\"alg-sparse-dyn-attn-sec-8\">八 · 运动能量估计：代理路径的输入、输出与摊销代价</h3>\n<p>数据流的第一站不是注意力本身，而是显著性代理。输入是当前扩散步的潜变量张量 <span class=\"inline-code\">z ∈ R^{F×H×W×C}</span>（F 为帧数，H/W 为潜空间分辨率），输出是逐 token 的运动能量向量 <span class=\"inline-code\">e ∈ R^{N}</span>，其中 N = F·(H/p)·(W/p) 为按 patch 划分的 token 数。两条实现路径：其一是对潜变量做时间差分，<span class=\"inline-code\">e_i = ‖∇_t z_i‖</span>，即同一空间位置相邻帧潜变量的 L2 差分，零额外网络、零额外显存，代价是一次跨帧读取——在 Blackwell 上这相当于把 F 帧的潜变量再扫一遍 HBM，带宽开销与一次 elementwise kernel 同量级；其二是轻量代理网络（数层卷积或小 ViT），输入为下采样潜变量，输出能量图，代价是每步一次前向，FLOPs 相对主干可忽略但引入了额外 kernel 启动与权重驻留。</p>\n<p>关键工程判断在于分辨率：代理不必在全分辨率上跑。把潜变量先做 2× 或 4× 下采样再估能量，能量图按最近邻上采样回 token 网格，估计开销按面积平方下降，而运动显著性本身是低频信号，下采样几乎不损失 top-k 的排序质量。这一步的输出必须与后续掩码构建的粒度对齐——若掩码以 16×16 的 MMA 分块为单位，能量也应按块聚合（块内取均值或最大值），否则逐 token 排序会在下一步被分块规则抹平。显存侧，能量向量本身是 O(N) 的，可忽略；真正占坑的是为差分而保留的上一帧潜变量，这在长视频下是 F 分之一的潜变量显存，属于必须常驻的额外开销。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-9\">九 · Top-K 选择与掩码构建：排序的代价与分块的对齐</h3>\n<p>第二步把能量向量变成布尔掩码。输入 <span class=\"inline-code\">e</span>，输出显著 token 集合 <span class=\"inline-code\">S = TopK(e)</span> 与掩码 <span class=\"inline-code\">M_{ij} = 1[i ∈ S 且 j ∈ S]</span>。注意掩码定义在 token 对上而非单 token 上：只有两端都显著的对才参与计算，这使稀疏度按 <span class=\"inline-code\">|S|²/N²</span> 的量级收缩，比单边稀疏更激进。Top-K 的实现代价取决于 K 与 N 的比例：小 K 可用 radix select，一趟扫描加直方图，O(N)；大 K 接近 N/2 时排序网络更划算。在 GPU 上这一步是典型的低算术强度 kernel，瓶颈在 HBM 读 <span class=\"inline-code\">e</span> 与写索引，延迟在微秒级，但它是串行的——必须等能量估计完成才能启动，构成注意力关键路径上的一段不可重叠的间隙。</p>\n<div class=\"formula\">$$M_{ij}=\\mathbb{1}\\left[i\\in\\mathrm{TopK}(e)\\ \\text{且}\\ j\\in\\mathrm{TopK}(e)\\right],\\quad \\text{sparsity}=1-\\frac{\\sum_i|\\mathcal{S}_i|}{N^2}$$</div>\n<p>掩码构建的真正代价不在排序而在形状。tcgen05 的 MMA 以规则分块（如 128×128 或 64×N）消费操作数，TMEM 的累加器布局也按固定 tile 组织。若掩码是逐 token 的任意布尔图，硬件无法跳过块内零散的非零对，只能整块计算再屏蔽，于是有效稀疏度被\"块内填充率\"稀释：一个 128×128 块里只要有少量显著对，整块就得算。工程上的对策是把 Top-K 结果先聚合到块粒度，按块内显著对比例决定该块是 dense、sparse 还是跳过，形成三级掩码。这一步的输出因此不是一张位图，而是一张块级调度表——它决定了下一步 kernel 的 grid 形状与每个 CTA 的工作量，也决定了负载均衡：显著块在帧间分布不均时，部分 CTA 会空转。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-10\">十 · 掩码内 QK^T 与 PV：稀疏算子的实际吞吐</h3>\n<p>第三步是唯一产生注意力 FLOPs 的环节。输入为 Q、K、V 三份投影后的张量（即该算法语境下的 QKV 缓存）与块级调度表，输出为稀疏注意力结果 <span class=\"inline-code\">O_i</span>。对每个显著块，计算 <span class=\"inline-code\">Q_i K_j^T/√d</span> 经 softmax 后与 <span class=\"inline-code\">V_j</span> 相乘；对非显著块，输出直接置零或走捷径（把该 token 的输出标记为待残差补足）。理论 FLOPs 为：</p>\n<div class=\"formula\">$$\\text{FLOPs}\\propto\\sum_{i}|\\mathcal{S}_i|,\\quad O_i=\\sum_j M_{ij}\\,\\mathrm{softmax}(Q_iK_j^{\\top}/\\sqrt{d})V_j$$</div>\n<p>实际吞吐与理论值的差距来自三处。其一，softmax 的归一化分母只在显著集合上求和，这意味着每个 query 行的分母不同，无法用整块统一的归约指令，需要在 TMEM 里做行级累加再广播，增加了寄存器压力与指令数。其二，稀疏块的行列索引不规则，K/V 的加载无法用连续的 TMA 大块传输，退化为按块索引的 gather，HBM 带宽利用率下降——这正是\"实际加速比常低于理论稀疏度\"的物理来源。其三，2-SM MMA 的配对协作要求两个 SM 处理同一块的互补部分，块级调度表若不能保证配对块同时就绪，协作退化为单 SM，吞吐减半。因此在稀疏度高但块填充率低的情形下，算子可能比全注意力更慢：算得少，但喂不饱张量核心。</p>\n<p>具体例子：一段长视频、高分辨率生成请求，F 帧、潜空间 token 数 N 较大，运动区域集中在画面中部的少数物体上。若按块粒度统计，显著块占比远小于逐 token 显著比例，则 kernel 的实际工作量由显著块数决定，而非 top-k 的 K 值。此时把 K 调大反而可能提升吞吐——更多块变成 dense，加载与调度更规则，稀疏带来的索引开销被摊薄。这是稀疏注意力在 Blackwell 上反直觉的调参方向。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-11\">十一 · 掩码跨步复用：运动连续性的假设与刷新代价</h3>\n<p>第四步不是计算而是复用。扩散采样在相邻步之间潜变量变化平滑，运动方向与显著区域高度相关，因此掩码可按帧间运动连续性在相邻步复用：第 t 步沿用第 t−1 步的块级调度表，跳过能量估计与 Top-K，直接进入稀疏 QK^T。输入是上一步的调度表与当前步的 QKV，输出是当前步的稀疏输出。代价收益很直接：代理估计与排序的开销被摊薄到每 r 步一次，r 为复用步数；在代理网络路径下，这等于把一次前向的固定开销除以 r，在端到端时延中占比进一步压缩。</p>\n<p>代价是正确性风险。复用假设运动连续，一旦运动方向突变（快速平移、物体突然入场、遮挡解除），旧掩码持续跳过新显著区域，稀疏注意力在这些 token 上输出为零或捷径值，残差路径无法补足缺失的注意力信息，表现为画面局部停滞或纹理不更新。工程上的折中是在复用期内插入轻量校验：用低成本的帧间差分监测能量分布的整体漂移量，超过阈值即强制刷新掩码；或采用交错复用，奇数步用旧掩码、偶数步重估，把最坏情况的滞后限制在两步内。刷新本身是一次代理前向加排序，其延迟在长视频下与一次稀疏注意力的量级可比，因此 r 的选择本质是\"摊销收益\"与\"突变漏检\"之间的定量权衡，而非固定常数。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-12\">十二 · 稠密残差相加：数值稳定与显存带宽的最后一跳</h3>\n<p>最后一步把稀疏结果与稠密残差路径合并：<span class=\"inline-code\">Õ_i = O_i + R_i</span>。R 来自一条并行的稠密通路——可以是对 V 的简单线性投影、局部窗口注意力的输出，或恒等捷径。其作用是双重的：数值上，稀疏输出的行和在显著集合上归一化，量级与稠密输出不一致，直接送入后续 LayerNorm 会造成分布偏移；残差把稀疏部分视为增量，主量级由稠密路径承担，避免了 softmax 分母在稀疏集合上过小导致的数值放大。工程上，这一步是一次 elementwise 加法，代价是读写两份 O(N·d) 的张量，在长视频高分辨率下这是纯粹的 HBM 带宽开销，且无法与上一步的 MMA 重叠——必须等稀疏输出写回后才能相加。</p>\n<p>这条残差路径也解释了本算法与缓存级复用的分野：它属于注意力算子级稀疏，稠密残差是算子内部的一部分，不是跨请求的 KV 复用。因此在显存账本上，QKV 缓存仍按全量驻留（稀疏只减少计算，不减少缓存），显存占用随帧数与分辨率增长，规模上限由帧数×分辨率的 KV 容量与带宽共同约束，而非由稀疏度决定。部署上配合 FP8/NVFP4 量化可压低这份缓存的字节数，但量化误差会与稀疏漏检叠加：被跳过的区域本就没有注意力校正，量化再引入偏移，细节丢失更明显。单卡或单节点张量并行的拓扑下，掩码与调度表需在 TP 组内广播一致，否则各 rank 计算的块集合不同，all-reduce 前的部分和无法对齐——这是稀疏掩码在并行部署中最容易踩的坑。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-13\">十三 · 边界、失效条件与系统代价：稀疏掩码在 Blackwell 上的真实收益账</h3>\n<p>把机制步骤落到工程上，最先要盯的是“理论稀疏度”与“硬件可执行稀疏度”之间的差额。掩码 $M_{ij}=\\mathbb{1}[i\\in\\mathrm{TopK}(e)\\ \\text{且}\\ j\\in\\mathrm{TopK}(e)]$ 是按 token 索引任意挑选的，而 Blackwell 的 tcgen05 MMA 走的是 TMEM 上规则分块的 K 维与 N 维；一旦被选中的 token 对在块内不成片，张量核心要么退化为按块整算、把未选中的 token 一起拖进来，要么切到更细的 MMA 形状，单次指令的利用率下降。于是实际加速比常低于 $1-\\sum_i|\\mathcal{S}_i|/N^2$ 给出的账面值，在分块约束严格的档位上收益被大幅压缩。工程判断是：选 top-k 时不要按纯能量排序散点取，而应按块对齐的粒度做块级 top-k，把稀疏度定义在 64/128 这类块宽上，让掩码天然成片；代价是块内混入低能量 token，有效稀疏度略降，但换来的规则分块能让 MMA 与 TMEM 带宽都吃满。</p>\n<p>第二个失效面在显著性估计本身。$e_i=\\|\\nabla_t z_i\\|$ 或轻量代理网络的输出，对快速运动与遮挡区域天然不敏感：光流在遮挡边界无定义，下采样潜变量又把小物体的位移抹平。漏检的直接后果是这些 token 被排除在 $\\mathcal{S}_i$ 之外，输出只剩稠密残差路径 $R_i$ 兜底，表现为运动物体边缘模糊、遮挡处纹理跳变与逐帧闪烁。更隐蔽的是掩码复用：按帧间运动连续性在相邻去噪步沿用同一掩码，估计开销被摊薄，但若运动方向突变而掩码未及时刷新，稀疏注意力会持续跳过新显著区域，画面局部停滞。因此复用必须有失效判据——用代理能量的帧间差分或掩码覆盖率变化触发强制重估，把“复用省下的算力”与“漏检造成的重算/返工”放在同一本账上算。</p>\n<p>系统代价要按请求生命周期拆开看。代理估计这一步的输入是下采样潜变量或光流，输出是每 token 能量与 top-k 索引，代价是额外一次前向与一次排序，显存上多一份能量张量与索引张量；在批大小 1–4、固定分辨率长视频的配方下，这部分开销相对注意力主干很小，但它落在关键路径上，直接抬高首步时延。掩码构建与 QKV 缓存的组织也要算：稀疏注意力所需的 QKV 缓存随帧数与分辨率线性增长，掩码本身是 $O(N^2)$ 的位图，若按位压缩存储可摊薄带宽，若按布尔张量存则会在长视频上反噬显存。真正决定端到端时延的是掩码内 QK^T 与 PV 的规模，$$\\mathrm{FLOPs}\\propto\\sum_{i}|\\mathcal{S}_i|$$ 只在掩码成片、块利用率接近 1 时才近似成立；否则有效 FLOPs 要乘上一个由块对齐率决定的分块惩罚因子。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>输入→输出</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>代理估计</td><td>下采样潜变量/光流→每 token 能量 $e_i$</td><td>额外前向，抬高首步时延</td><td>快速运动、遮挡边界漏检</td></tr><tr><td>top-k 掩码</td><td>$e_i$→块对齐掩码 $M_{ij}$</td><td>排序与位图显存，$O(N^2)$ 索引</td><td>散点选取破坏规则分块</td></tr><tr><td>稀疏 MMA</td><td>掩码内 QKV→$O_i$</td><td>块利用率下降，加速比低于理论值</td><td>块内不成片，TMEM 带宽浪费</td></tr><tr><td>掩码复用</td><td>相邻步掩码→沿用</td><td>省去重复估计</td><td>运动突变未刷新，局部停滞</td></tr><tr><td>残差相加</td><td>$O_i+R_i$→$\\tilde O_i$</td><td>稠密路径常驻，显存不降</td><td>稀疏过度时残差主导，收益归零</td></tr></tbody></table>\n<p>由此得出适用边界的定量直觉：收益随稀疏度上升，但被两个因子夹住——块对齐率 $\\rho$ 与漏检率 $\\epsilon$。有效加速近似正比于 $\\rho\\cdot(1-\\text{sparsity})$，而画质损失随 $\\epsilon$ 单调上升；当 $\\rho$ 低到使有效加速趋近 1，或 $\\epsilon$ 高到残差路径已无法掩盖闪烁时，这套方案就该退回固定局部窗口或全注意力。规模上限则卡在帧数与分辨率带来的显存与带宽：掩码位图与 QKV 缓存同步增长，单卡或单节点张量并行的拓扑下，超过显存档位能容纳的帧数后，稀疏省下的算力会被缓存搬运吃掉。配合 FP8/NVFP4 量化时还要注意，稀疏跳过的 token 不参与量化缩放统计，残差路径的数值范围需单独校准，否则 $\\tilde O_i=O_i+R_i$ 的稳定性技巧会在低精度下失效。</p>\n<h3 id=\"alg-sparse-dyn-attn-sec-14\">十四 · 从运动能量到掩码：显著性估计的可实现形式</h3>\n<p>核心公式的第一项不是注意力本身，而是显著性度量。给定潜变量序列 $z_i$（$i$ 遍历帧×空间位置的 token 索引），最轻量的定义是沿时间轴的有限差分能量：</p>\n<div class=\"formula\">$$e_i=\\|\\nabla_t z_i\\|=\\|z_i^{(t+1)}-z_i^{(t)}\\|_2$$</div>\n<p>这一步的推导关键在于：注意力权重 $s_{ij}=Q_iK_j^\\top/\\sqrt{d}$ 的大小由 query 与 key 的内容相关性决定，而视频中真正需要跨帧交互的 token，恰恰是那些内容随时间发生变化的 token——静止背景 token 的 $Q_i$ 在相邻帧几乎不变，其注意力分布趋于均匀且信息量低。因此用 $\\nabla_t z_i$ 作为 $e_i$ 的代理，等价于假设“时间导数大的 token 才是注意力预算的合理去处”。工程上这个假设的代价极低：一次差分只需读写一遍潜变量，带宽开销是 $O(Nd)$ 量级，相比全注意力的 $O(N^2d)$ 可以忽略。</p>\n<p>当差分代理不够用时（快速运动导致帧间位移超过一个 patch，差分能量在错误位置峰值），改用轻量代理网络或光流估计：对下采样后的潜变量跑一个 2–3 层卷积，输出每 token 的运动能量。这里的系统代价必须算清楚：代理网络本身是一次前向，其 FLOPs 与潜变量分辨率成正比而非与帧对数平方成正比，因此在长视频上它被摊薄；但它引入一次额外的 kernel 启动与显存往返，在短序列、小 batch 场景下反而可能吃掉稀疏带来的收益。这就是为什么掩码复用机制（下一节）不是可选项而是必需品。</p>\n<p>具体例子：一个 512×512 分辨率、49 帧的潜变量序列，patch size 2 时空间 token 数为 $256\\times256=65536$，总 token 数约 $3.2\\times10^6$。逐 token 差分需要读写约 3.2M×通道数的元素，在 Blackwell 的单卡 HBM 带宽下是毫秒级的一次遍历；而全注意力的 QK^T 需要 $N^2$ 次乘加，$N^2\\approx10^{13}$，这是稀疏化存在的全部理由。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-15\">十五 · TopK 掩码的构造与稀疏度定义</h3>\n<p>拿到能量向量 $e\\in\\mathbb{R}^N$ 后，掩码的定义是双向的：</p>\n<div class=\"formula\">$$M_{ij}=\\mathbb{1}\\left[i\\in\\mathrm{TopK}(e)\\ \\wedge\\ j\\in\\mathrm{TopK}(e)\\right]$$</div>\n<p>注意这里是“与”而非“或”。若只用 $i\\in\\mathrm{TopK}$ 单向筛选，保留的 token 对数量是 $k\\cdot N$，稀疏度只有 $1-k/N$，随 $N$ 线性而非平方下降，长视频上收益迅速消失。双向筛选把保留对数压到 $k^2$，于是：</p>\n<div class=\"formula\">$$\\text{FLOPs}\\propto\\sum_i|\\mathcal{S}_i|=k^2,\\qquad \\text{sparsity}=1-\\frac{k^2}{N^2}$$</div>\n<p>推导的关键一步在此：$\\sum_i|\\mathcal{S}_i|$ 在双向掩码下恰好等于 $|\\mathrm{TopK}(e)|^2$，因为每个被选中的 query 只在被选中的 key 集合上求和。这使 FLOPs 对 $k$ 呈二次依赖——$k$ 减半，注意力算力降到四分之一。工程判断因此变得直接：$k$ 的选择不是“保留多少比例”的模糊调参，而是直接决定算力预算的平方根级杠杆。代价是 $k$ 过小会漏掉中等运动 token，表现为运动物体边缘的细节丢失。</p>\n<p>排序本身的开销不可忽视。对 $N\\approx3.2\\times10^6$ 做全排序是 $O(N\\log N)$，在 GPU 上通常用分块 top-k 近似：先按块求块内最大值，再在块级候选上做精确选择。这一步的显存代价是需要一个与 $e$ 同尺寸的临时缓冲，在 batch=4、高分辨率下这可能是数百 MB 级；因此实现上常把能量估计与 top-k 融合进一个 kernel，避免物化完整能量向量。</p>\n<p>具体例子：设 $N=3.2\\times10^6$，取 $k=4096$，则保留对数 $k^2\\approx1.7\\times10^7$，相对 $N^2\\approx10^{13}$ 的稀疏度为 $1-1.7\\times10^{-6}$，理论 FLOPs 下降五个数量级以上。但下一节会说明，这个理论值几乎不可能被硬件兑现。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-16\">十六 · 稀疏注意力的逐项展开与残差路径</h3>\n<p>掩码内的注意力计算与标准注意力同构，只是求和域被裁剪：</p>\n<div class=\"formula\">$$O_i=\\sum_{j}M_{ij}\\,\\mathrm{softmax}\\!\\left(\\frac{Q_iK_j^\\top}{\\sqrt{d}}\\right)V_j,\\qquad \\tilde O_i=O_i+R_i$$</div>\n<p>逐项解释：$M_{ij}$ 是硬 0/1 门，它同时承担两个作用——裁剪求和域，以及在被裁剪的位置上把 softmax 的输入置为 $-\\infty$（实现上是加一个大的负偏置），保证归一化只在保留集合内进行。若不做这一步而直接对未裁剪的 $s_{ij}$ 做 softmax 再乘 $M$，归一化分母会包含被丢弃的项，输出幅值被系统性压低，这正是稀疏注意力数值不稳定的主要来源之一。$\\sqrt{d}$ 缩放保持与稠密注意力一致，使 $Q,K$ 的量化尺度（FP8 或 NVFP4）可以沿用同一套校准参数。</p>\n<p>残差项 $R_i$ 是稠密路径的输出，通常取一个低成本近似：局部窗口注意力、或上一时间步的缓存输出、或直接是 $V_i$ 自身的线性投影。$\\tilde O_i=O_i+R_i$ 的推导依据是：稀疏路径提供跨帧的长程交互，残差路径保证每个 token 至少有一条不依赖掩码正确性的信息通路。当显著性估计漏检时，$O_i$ 对该 token 贡献接近零，输出退化为 $R_i$，画面不会出现整块塌陷，而是退化为局部窗口的质量——这是“细节丢失与闪烁”而非“结构性崩坏”的分界线。代价是残差路径本身要花算力，若取局部窗口，其 FLOPs 为 $O(Nw)$（$w$ 为窗口大小），在 $k$ 很小时它可能成为主导项，压缩了稀疏化的净收益。</p>\n<p>具体例子：在 Blackwell 上，$O_i$ 的计算要走 tcgen05 的 2-SM MMA 路径以获得峰值吞吐，但 $k^2$ 个保留对在 token 维度上是散乱索引，必须先做 gather 重排成连续块。这次 gather 的显存流量与 $k\\cdot d$ 成正比，在 $k=4096$、$d=128$、FP8 下约 0.5 MB 级，单次开销小，但它打断了 MMA 流水，是实际加速比低于理论值的第一个来源。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-17\">十七 · 掩码复用的时间连续性假设与刷新策略</h3>\n<p>扩散推理的每一步都重新估计能量是纯粹的浪费：相邻去噪步之间，潜变量的运动结构高度相关。复用规则可写成：</p>\n<div class=\"formula\">$$M^{(t+1)}=\\begin{cases}M^{(t)}, &amp; \\|\\bar e^{(t+1)}-\\bar e^{(t)}\\|&lt;\\tau\\\\ \\mathrm{rebuild}, &amp; \\text{otherwise}\\end{cases}$$</div>\n<p>其中 $\\bar e$ 是能量向量的低阶矩（均值、或分块均值），$\\tau$ 是刷新阈值。推导的关键一步是把“掩码是否仍然有效”这个全局判断降维成对低阶统计量的比较——这样判断本身的代价是 $O(\\text{块数})$ 而非 $O(N)$，可以在 host 侧或一个极小的 kernel 里完成。复用带来的收益是代理估计与 top-k 排序的开销被摊薄到 $1/T_{\\text{reuse}}$，$T_{\\text{reuse}}$ 为复用步数。</p>\n<p>代价在失败模式上：运动方向突变（遮挡解除、物体突然加速）时，旧掩码持续跳过新显著区域，稀疏路径对该区域输出为零，画面局部停滞。工程上的缓解不是缩短复用周期（那会吃掉收益），而是在残差路径里保留一个对能量变化敏感的分量——例如把 $\\|\\nabla_t z_i\\|$ 超过阈值的 token 强制并入 $R_i$ 的局部窗口，使突变区域至少获得窗口级交互。这是“掩码复用”与“残差路径”两个机制必须联合设计的根本原因。</p>\n<p>具体例子：49 帧序列在 20 步去噪中，若每 4 步重建一次掩码，代理网络只跑 5 次而非 20 次，其前向开销降到四分之一；但若第 12 步发生大面积遮挡解除，第 9 步建立的掩码会一直用到第 12 步，这 3 步内的新显著区域只能靠残差路径兜底。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-18\">十八 · 落到可实现：伪代码与分块约束</h3>\n<p>把上述公式落成一个可在 Blackwell 上跑的 kernel 序列，关键约束是 MMA 要求操作数按固定 tile（如 128×128）对齐，而 top-k 索引是散乱的。可实现的路径是“先 gather 后 MMA”：</p>\n<ul>\n<li>步骤 A：能量估计 kernel，输出 $e$ 与分块最大值；</li>\n<li>步骤 B：块级 top-k 选择，得到保留 token 的索引表 $\\mathcal{I}$（长度 $k$），并写入连续缓冲；</li>\n<li>步骤 C：按 $\\mathcal{I}$ 对 $Q,K,V$ 做 gather，得到 $Q'\\in\\mathbb{R}^{k\\times d}$、$K'\\in\\mathbb{R}^{k\\times d}$、$V'\\in\\mathbb{R}^{k\\times d}$；</li>\n<li>步骤 D：对 $Q'K'^\\top$ 走标准分块 MMA 与 softmax，得到 $O'\\in\\mathbb{R}^{k\\times d}$；</li>\n<li>步骤 E：按 $\\mathcal{I}$ scatter 回 $O$，未选中位置置零；</li>\n<li>步骤 F：$\\tilde O=O+R$，$R$ 由局部窗口 kernel 并行产出。</li>\n</ul>\n<p>伪代码思路（不写成代码块）：对每个 batch 项，先在 $e$ 上做一次两级归约得到块级候选，再用一个 warp 级 bitonic 排序在候选集上选出 $k$ 个索引；索引表写入 shared memory 后，gather kernel 以 $k/128$ 个 tile 为单位发起，每个 tile 的 128 个 token 索引由索引表连续段提供。这里的系统代价是 gather/scatter 两次显存往返，流量约 $3kd$（gather QKV）加 $kd$（scatter O），在 FP8 下相对 $k^2d$ 的 MMA 计算量仍是小项，但它决定了 kernel 启动次数与流水断点。</p>\n<p>具体例子：$k=4096$、$d=128$、FP8，gather 流量约 $4\\times4096\\times128\\approx2$ MB/层/步；一个 32 层的视频 DiT 在 20 步去噪、batch=2 下，这部分额外流量累计到 GB 级，与 KV 缓存本身的占用同量级——这是稀疏注意力在显存带宽上并非“免费”的直接体现。分块约束还意味着 $k$ 应取 128 的整数倍，否则最后一个 tile 需要 padding，padding 部分参与 MMA 但不参与输出，浪费的算力比例约为 $1-(k\\bmod128)/128$。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-19\">十九 · 稀疏度、加速比与容量规划的三方约束</h3>\n<p>理论稀疏度与实际加速比之间的差距，可以写成一个可测量的比值：</p>\n<div class=\"formula\">$$\\eta=\\frac{T_{\\text{dense}}-T_{\\text{sparse}}}{T_{\\text{dense}}}\\Big/\\ \\text{sparsity}$$</div>\n<p>$\\eta$ 是稀疏化的兑现率。分子是实测时延下降比例，分母是公式给出的理论稀疏度。$\\eta$ 的上界由三件事决定：gather/scatter 的固定开销、padding 浪费、以及残差路径的相对成本。当 $k$ 很小而残差窗口 $w$ 固定时，残差项 $O(Nw)$ 不随 $k$ 下降，$\\eta$ 会被残差项拉低——这解释了为什么“稀疏度越高越好”是错的：存在一个 $k$ 的下界，低于它净收益转负。</p>\n<p>容量规划因此要把三个量放在一起看：显存（KV 缓存随帧数与分辨率线性增长，稀疏化不减少缓存本身，只减少对缓存的访问次数）、带宽（gather/scatter 与残差路径的流量）、算力（$k^2$ 的 MMA）。在单卡或单节点张量并行的部署档位上，batch 取 1–4 时，显存是硬约束，稀疏化的作用是让长视频在高分辨率下不撞上注意力算力墙，而不是省显存。SLO 以端到端时延为主时，$\\eta$ 的实测值应作为容量模型里的乘性因子，而不是用理论稀疏度直接外推。</p>\n<p>具体例子：若某层实测 $\\eta=0.3$，理论稀疏度 $1-k^2/N^2$ 在 $k=4096$、$N=3.2\\times10^6$ 下接近 1，则时延实际只下降约三成——这个数字必须进入容量模型，否则按理论值做的 SLO 承诺会系统性落空。工程判断落在 $k$ 与 $w$ 的联合选择上：先固定残差窗口 $w$ 使其成本可忽略，再在 $\\eta$ 的实测曲线上找 $k$ 的拐点，而不是先定稀疏度再倒推。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-20\">二十 · 掩码落地时的分块代价与漏检边界</h3>\n<p>把 <span class=\"formula\">$$M_{ij}=\\mathbb{1}[i\\in\\mathrm{TopK}(e)\\ \\text{且}\\ j\\in\\mathrm{TopK}(e)]$$</span> 直接翻译成 kernel 会立刻撞上硬件约束：tcgen05 的 MMA 以固定形状的 tile 为单位发射，稀疏掩码若在 tile 内部留下空洞，张量核心仍要按整块搬运并计算，被跳过的 token 对只省下寄存器写回而非 MMA 周期。因此可实现的做法是把 TopK 集合先按 tile 边界对齐，得到块粒度掩码 <span class=\"formula\">$$\\tilde M_{ab}=\\mathbb{1}\\big[\\exists\\,(i,j)\\in(a,b):M_{ij}=1\\big],$$</span> 再对 <span class=\"formula\">$$\\tilde M_{ab}=0$$</span> 的块整体跳过 QK^T 与 PV。代价是有效稀疏度被块粒度稀释，理论 FLOPs 下降 <span class=\"formula\">$$\\text{sparsity}=1-\\sum_i|\\mathcal{S}_i|/N^2$$</span> 而实测加速比按块对齐后的非零块比例结算，块越大稀释越重；在 128×128 的 tile 下，零散分布的显著 token 几乎无法形成整块跳过，收益被大幅压缩。这就是该方案在规则分块要求严格的档位上必须优先调 tile 形状、而非一味调高 k 的原因。</p>\n<p>漏检是另一条硬边界。能量估计 <span class=\"formula\">$$e_i=\\|\\nabla_t z_i\\|$$</span> 在低分辨率潜变量上做帧间差分，快速运动物体在相邻帧位移超过一个潜变量像素时差分反而变小，遮挡区域的纹理跳变也会被平滑掉；这两类 token 落不进 TopK，输出 <span class=\"formula\">$$O_i=\\sum_j M_{ij}\\,\\mathrm{softmax}(Q_iK_j^{\\top}/\\sqrt{d})V_j$$</span> 便缺失关键上下文，表现为运动物体边缘模糊与遮挡处纹理闪烁。缓解手段不是加大 k，而是把稠密残差 <span class=\"formula\">$$\\tilde O_i=O_i+R_i$$</span> 保留为低带宽捷径——残差路径不参与稀疏掩码，代价是它仍要付出与帧数成正比的显存与带宽，稀疏省下的是 MMA 算力而非 KV 缓存本身，显存占用随帧数与分辨率继续增长，批大小只能压在 1–4 档。</p>\n<p>掩码按帧间运动连续性复用时，失效条件很具体：运动方向突变而掩码未刷新，稀疏注意力会持续跳过新出现的显著区域，画面局部停滞。工程判断是把复用周期与代理估计开销绑定——估计本身是轻量网络或光流，摊薄它的唯一办法是拉长复用步数，而拉长复用步数直接放大突变漏检风险，二者构成该方案的核心调参张力。可行折中是按帧间能量变化率触发强制刷新，而非固定步数复用；刷新帧付出完整估计开销，其余帧走复用掩码，使代理开销在长视频序列上被摊薄的同时给突变留出检测窗口。</p>\n<table class=\"mini\"><thead><tr><th>失效来源</th><th>系统表现</th><th>代价落点</th></tr></thead><tbody><tr><td>掩码破坏规则分块</td><td>加速比低于理论稀疏度</td><td>MMA 周期未减，仅省写回</td></tr><tr><td>快速运动/遮挡漏检</td><td>边缘模糊、纹理闪烁</td><td>稠密残差兜底，显存不降</td></tr><tr><td>复用掩码未刷新</td><td>局部画面停滞</td><td>强制刷新帧的估计开销</td></tr></tbody></table>\n<h3 id=\"alg-sparse-dyn-attn-sec-21\">二十一 · 请求形态：固定分辨率长视频才是主战场</h3>\n<p>动态稀疏时空注意力的负载配方第一条不是参数，而是请求形态。它吃的是「固定分辨率、长时长、运动区域局部化」的扩散推理请求：分辨率在整条请求内不变，帧数拉长，镜头内容以缓慢运镜或主体局部运动为主。这种形态下，每帧的潜变量网格是稳定的，token 运动能量 <span class=\"inline\">$e_i=\\|\\nabla_t z_i\\|$</span> 的排序在相邻去噪步之间具有连续性，掩码复用才有意义。反过来，如果请求是分辨率频繁切换的短片段拼贴、镜头切换密集的蒙太奇、或整幅画面都在剧烈运动的场景（手持晃动、爆炸粒子、水面全域波动），运动能量在 token 维度上接近均匀分布，TopK 选出的显著集合几乎覆盖全图，稀疏度趋近于零，算法退化为带额外代理估计开销的全注意力——付出估计成本却拿不到跳过收益。</p>\n<p>工程上判断一个请求是否落在配方内，看两个可测指标：其一是显著 token 占比的估计值，用低分辨率代理在首步跑一遍能量排序，若 TopK 集合占全部 token 的比例超过某个内部阈值（取决于目标稀疏度档位），该请求应回退到稠密路径；其二是帧间能量排序的 Kendall 秩相关系数，秩相关高说明掩码可跨步复用，秩相关低说明每步都得重估，代理开销摊薄不了。这两个指标都能在请求进入调度队列时用一次轻量前向算出，作为路由依据，而不是等跑完再发现加速比不达标。</p>\n<p>代价落在调度侧：请求形态判断本身要占用一次代理前向，其开销与下采样潜变量的规模成正比，在批内混入形态不符的请求时，这条代理路径会成为批内最慢成员的隐性成本，拉长整批的端到端时延。因此形态路由必须发生在组批之前，而不是批内。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-22\">二十二 · 长度分布：帧数增长改变的是显存与带宽，不只是 FLOPs</h3>\n<p>长度分布对这条算法的影响是非线性的，因为稀疏化只压注意力 FLOPs，不压 QKV 缓存的驻留量。稀疏注意力的输出为</p>\n<div class=\"formula\">$$O_i=\\sum_j M_{ij}\\,\\mathrm{softmax}(Q_iK_j^{\\top}/\\sqrt{d})V_j,\\qquad \\tilde O_i=O_i+R_i$$</div>\n<p>掩码 <span class=\"inline\">$M_{ij}$</span> 决定算哪些 token 对，但 <span class=\"inline\">$K$</span>、<span class=\"inline\">$V$</span> 仍要为全部帧的 token 保留，稠密残差路径 <span class=\"inline\">$R_i$</span> 也要求全量隐状态可达。于是帧数翻倍时，注意力 FLOPs 因稀疏度固定而近似线性增长（<span class=\"inline\">$\\text{FLOPs}\\propto\\sum_i|\\mathcal{S}_i|$</span>），但 QKV 缓存与残差路径的显存占用按帧数×分辨率平方增长，带宽压力来自对全量 <span class=\"inline\">$K/V$</span> 的搬运而非仅对掩码内块的搬运。这意味着长度分布的尾部——少数超长请求——决定了显存档位，而中位数请求决定吞吐。</p>\n<p>配方上的处理是把长度分布切成离散档：短档走稠密或轻稀疏，中档走标准 TopK 稀疏，长档必须配合分块流式与 KV 驻留策略（那部分属于其他片段，此处只指路）。同一批内混装跨档请求会让批内最长的成员拖住整批的显存峰值与步进节奏，连续批处理在这种情况下反而放大抖动。具体例子：一批四条请求，三条为中等帧数、一条为超长帧数，超长那条的 QKV 缓存把整批推到显存上限，调度器被迫降低并发，三条中等请求的吞吐被一条长请求绑架——这正是长度分布未分档的直接后果。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-23\">二十三 · 并发与批大小：1–4 的批是显存约束下的产物</h3>\n<p>材料给出的批大小配方是按显存档位取 1–4，SLO 以端到端时延为主。这个窄批区间不是保守，而是被两个因素夹出来的：一是长视频高分辨率下 QKV 缓存与残差路径的显存占用随帧数与分辨率增长，批内每条请求都自带一份全量缓存，批大小直接乘在显存峰值上；二是稀疏掩码破坏张量核心的规则分块，实际加速比低于理论稀疏度，单条请求的算力利用率本就不满，靠堆批来填满 SM 的收益被掩码不规则性抵消。</p>\n<p>并发维度的关键判断是：这条算法的吞吐曲线在批大小超过某个点后不再上升，因为每增加一条请求，掩码构建与代理估计的固定开销按条累加，而掩码内的 MMA 分块因批内不同请求的显著集合互不相同而无法共享分块布局。批内请求的掩码若差异大，张量核心在每个分块上都要重新对齐，规则分块的浪费随批内掩码熵增而增。因此配方倾向于小批、多副本横向扩展，而不是大批纵向压榨。工程上可测的信号是每批的实际 MMA 占用率与理论稀疏度之比，比值随批大小下降即说明已过拐点。</p>\n<p>代价明确：小批意味着单卡并发低，端到端时延靠单条请求内部的稀疏跳过压下来，而不是靠批内并行隐藏延迟；吞吐则依赖多副本与请求排队策略。SLO 以时延为主时这是自洽的，但若负载转向吞吐优先的离线批处理，这套配方会让位给稠密路径或别的算子级方案。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-24\">二十四 · 负载不对时的三种崩法</h3>\n<p>第一种是稀疏度失效：请求运动区域稠密，TopK 集合覆盖全图，<span class=\"inline\">$\\text{sparsity}=1-\\sum_i|\\mathcal{S}_i|/N^2$</span> 趋近零，FLOPs 不降，反而多出代理估计与掩码构建的固定开销，端到端时延高于纯稠密路径。这不是精度问题，是纯亏损。</p>\n<p>第二种是分块破碎：即便稀疏度名义上很高，显著 token 在空间上散布而非聚成规则块，掩码内的 token 对无法拼成张量核心偏好的大分块，实际加速比被大幅压缩。材料明确指出这一失败模式在规则分块要求严格的档位上收益被大幅压缩。表现为理论 FLOPs 降了而实测时延没降，profiler 上看到的是 MMA 指令数下降但每指令的有效利用率同步下降。</p>\n<p>第三种是掩码复用导致的画面停滞：掩码按帧间运动连续性在相邻步复用时，若运动方向突变而掩码未及时刷新，稀疏注意力持续跳过新显著区域，画面局部停滞。这在镜头切换、快速遮挡、物体突然入画时最典型，表现为运动物体边缘模糊或遮挡处纹理跳变。它与显著性估计漏检是两类问题：漏检是估计本身不准，复用滞后是估计曾经准但没跟上变化。工程上的对策是给掩码复用加一个刷新触发器，用帧间能量排序的秩相关跌落作为信号强制重估，代价是那一 step 的代理开销不再被摊薄。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>配方内表现</th><th>失配后果</th></tr></thead><tbody><tr><td>固定分辨率、长时长、局部运动</td><td>稀疏度高，掩码可复用，时延显著下降</td><td>—</td></tr><tr><td>全域剧烈运动</td><td>稀疏度趋零</td><td>FLOPs 不降，叠加代理开销，纯亏损</td></tr><tr><td>显著 token 空间散布</td><td>名义稀疏度高</td><td>分块破碎，实测加速比远低于理论值</td></tr><tr><td>镜头切换/快速遮挡</td><td>掩码复用本应省开销</td><td>复用滞后，局部停滞与闪烁</td></tr></tbody></table>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-25\">二十五 · 配方与硬件的对齐：Blackwell 档位上的取舍</h3>\n<p>在 Blackwell 上部署这条算法，配方要与 tcgen05 的 MMA 分块形态对齐。稀疏掩码若不能映射成 2-SM MMA 可消费的规则块布局，TMEM 的搬运与累加节奏就会被打断，稀疏带来的指令数下降被数据搬运的碎片化吃掉。因此配方里的 TopK 选择不应只按能量排序取前 k 个散点，而应按能量在分块粒度上聚合后再选块，把稀疏性做成块稀疏而非元素稀疏——这牺牲一点理论稀疏度，换回张量核心的规则性。这是本片段的核心工程判断：负载配方里的「稀疏度目标」应定义为块级稀疏度，而非 token 级稀疏度。</p>\n<p>量化配合 FP8/NVFP4 时，稀疏路径与稠密残差路径的数值路径要一致，否则残差相加处会出现精度断层；材料给出的稳定性技巧是稀疏结果与稠密残差路径相加保持数值稳定，这在低精度下尤其依赖两条路径的缩放因子对齐。显存侧，KV 即稀疏注意力所需的 QKV 缓存，其占用随帧数与分辨率增长，批大小 1–4 的约束正来自这里；带宽侧，掩码内块的 K/V 搬运是主要流量，块稀疏布局能提高每次搬运的有效字节占比。</p>\n<p>具体例子：一条固定 1080p 级分辨率、数百帧的长视频扩散请求，单卡批大小取 1，掩码按块粒度构建并跨步复用，代理估计每若干步刷新一次；若把同一请求与三条短请求混批，短请求的掩码熵拉低整批的 MMA 利用率，且长请求的缓存把显存推到上限——配方要求这类混装被形态路由挡在组批之前。功耗维度上，稀疏跳过降低的是 MMA 活跃周期，代理估计与掩码构建是短时高频的轻负载，整体功耗曲线比稠密路径平缓，但小批多副本的部署方式会把功耗摊到更多卡上，容量规划要按副本数而非单卡利用率算。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-26\">二十六 · 配方的边界条件与路由判据</h3>\n<p>把上述收敛成可执行的路由判据：请求进入时测显著 token 块占比与帧间能量秩相关；块占比低于阈值且秩相关高于阈值，进稀疏路径并按显存档位定批大小 1–4；块占比超阈值则回退稠密，避免纯亏损；秩相关低于阈值则进稀疏但关闭掩码复用、每步重估，用代理开销换画面稳定。运行中监控每批 MMA 占用率与理论块稀疏度之比，比值持续下滑说明批内掩码熵过高，触发拆批。</p>\n<p>边界在于：这套配方不适用于分辨率频繁变化或运动全域化的请求，也不适用于吞吐优先、批大小需要压到两位数的离线场景；规模上限受帧数与分辨率带来的显存与带宽约束，材料未给出具体上限数值，工程上应以 QKV 缓存加残差路径的显存峰值反推可支持的最大帧数，而不是以 FLOPs 预算反推。最终落在具体机制上：块级 TopK 选择加秩相关驱动的掩码刷新触发器，是这条算法在负载配方层面能否兑现「FLOPs 随稀疏度线性下降」的两个闸门，任何一个失守，理论稀疏度就只是纸面数字。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-27\">二十七 · 运动稀疏注意力的负载边界：何时收益兑现，何时反噬</h3>\n<p>这套方案的前提是请求形态与运动分布同时落在“稀疏可估”的区间内：固定分辨率的长视频生成、批大小按显存档位取 1–4、SLO 以端到端时延为主，且每帧真正参与运动的 token 只占少数。此时理论代价与实测代价的差距由分块规则性决定。设理论加速比为 $G_{\\text{ideal}}=1/\\text{sparsity}$，而张量核心要求 $16\\times16$ 或更粗的规则分块，掩码内 token 对若不能填满分块，实际加速比退化为 $G_{\\text{real}}\\approx \\frac{N^2}{\\sum_{b}\\lceil |\\mathcal{S}_{b}|/B^{2}\\rceil B^{2}}$，其中 $B$ 为分块边长。稀疏度越高、运动 token 越分散，$G_{\\text{real}}$ 与 $G_{\\text{ideal}}$ 的落差越大——这是该方案最先触到的墙，而非 FLOPs 本身。</p>\n<p>负载不对时，失效沿三条路径发生。其一是请求形态错配：短片段、低分辨率或镜头近乎静止的请求，代理估计与掩码构建的固定开销摊不薄，端到端时延反而高于全注意力；批大小被显存压到 1 时，单请求无法靠并发掩盖代理网络与排序的串行段。其二是长度分布错配：帧数增长使 QKV 缓存与掩码张量同步膨胀，显存与带宽成为主约束，稀疏省下的算力被缓存搬运抵消，长视频高分辨率下显存占用随帧数与分辨率线性增长，规模上限由这两项而非 FLOPs 决定。其三是运动分布错配：快速运动或遮挡区域的 token 能量被低估，漏检直接表现为运动物体边缘模糊、遮挡处纹理跳变与帧间闪烁。</p>\n<p>最隐蔽的一类是掩码复用与运动突变的对撞。掩码按帧间运动连续性在相邻步复用，代理估计开销被摊薄，但一旦运动方向突变而掩码未及时刷新，稀疏注意力会持续跳过新显著区域，画面局部停滞。工程判断是给复用加一道刷新触发器：当相邻步能量排序的 TopK 集合交并比 $J=|S_{t}\\cap S_{t-1}|/|S_{t}\\cup S_{t-1}|$ 低于阈值时强制重估，用一次代理前向的代价换掉整段画面的停滞风险。批量侧则应把批大小钉在显存能容纳掩码与 QKV 缓存的档位，宁可牺牲吞吐也不让分块碎片化吃掉加速比。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>收益兑现</th><th>失效表现</th></tr></thead><tbody><tr><td>长视频、高分辨率、运动稀疏</td><td>FLOPs 随稀疏度线性降，时延显著降</td><td>分块碎片化压缩实际加速比</td></tr><tr><td>短片段、近静止镜头</td><td>无</td><td>代理与排序开销摊不薄，时延反超全注意力</td></tr><tr><td>快速运动、遮挡频繁</td><td>局部</td><td>漏检致边缘模糊、纹理跳变、闪烁</td></tr><tr><td>运动方向突变</td><td>复用摊薄开销</td><td>掩码未刷新，新显著区域被持续跳过</td></tr></tbody></table>\n<h3 id=\"alg-sparse-dyn-attn-sec-28\">二十八 · 硬件档位：从单卡到 NVL72 的取舍线</h3>\n<p>动态稀疏时空注意力的部署档位不是按“越大越好”排的，而是按稀疏掩码能否被硬件规则分块吸收来排。SM100 的 tcgen05 与 2-SM MMA 要求操作数落在 TMEM 与规则 tile 上，稀疏掩码一旦把 K 维切成不规则片段，MMA 的 tile 形状就被迫退化，理论稀疏度与实测加速比之间出现结构性缺口。因此档位选择的第一判据是：本档位的分块粒度能否容纳 TopK 掩码的连通块长度。</p>\n<p>单卡 B200/B300 档位适合分辨率中等、帧数受限、批大小为 1 的长视频请求。此时稀疏度收益主要来自跳过整块 K tile：把 TopK 集合按 K 维 tile 对齐后再做 MMA，未被选中的 tile 直接不发射，避免逐元素掩码破坏 tensor core 的规则性。代价是显存：QKV 缓存随帧数与分辨率线性增长，单卡 HBM 容量决定了帧数上限，掩码复用只能摊薄代理估计开销，不能压缩缓存本身。</p>\n<p>GB200/GB300 NVL72 档位把并行拓扑推向单节点张量并行加跨节点流水。稀疏注意力的并行切分要沿头维与序列维同时做：头维切分天然适配张量并行，序列维切分则要求各 rank 的 TopK 集合在边界处对齐，否则跨 rank 的稀疏 PV 需要额外 all-to-all 交换被选中的 V 块。NVLink 5 的高带宽使这种交换可行，但通信量正比于被选中 token 数而非全量 token 数，这正是稀疏带来的通信红利。</p>\n<p>档位判断的量化口径是每步注意力时延中 MMA 时间与掩码构造、代理估计、跨 rank 交换时间的比值。若掩码构造与代理估计占比超过 MMA 时间，说明档位过高、稀疏度不足，应降档或提高稀疏度阈值；反之若 MMA 仍占主导且 tile 利用率低，说明掩码未对齐 tile，应改为 tile 级 TopK 而非 token 级 TopK。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-29\">二十九 · 并行拓扑：掩码对齐先于切分策略</h3>\n<p>并行拓扑的设计顺序应当是先定掩码的 tile 对齐方式，再定张量并行与序列并行的切分维度。token 级 TopK 在单卡上尚可，一旦跨 rank 切分序列维，边界 token 的显著邻居可能落在远端 rank，形成跨 rank 稀疏对。工程做法是把序列维按 tile 边界切分，并让每个 rank 在本地 TopK 之外额外保留一圈 halo token 的能量估计，使跨边界稀疏对能在本地判定是否需要远端 V 块。</p>\n<p>伪代码思路如下：每个 rank 先对本地潜变量做下采样代理估计得到 $e_i$，再对 halo 区做同样估计；随后在全局能量向量上做一次轻量 all-gather 或按分块最大值做近似排序，得到全局 TopK 集合；本地只对落在本 rank 且掩码命中的 tile 发射 QK^T 与 PV，跨 rank 命中的 tile 通过 NIXL 或 NCCL 拉取对应 V 块。全局排序的通信量正比于每 rank 的候选数而非全量 token 数，是可接受的固定开销。</p>\n<p>公式上，跨 rank 稀疏注意力的通信代价可写成被选中远端块数乘以块大小：</p>\n<div class=\"formula\">$$\\text{Comm}\\propto \\sum_{r}\\left|\\{j\\in\\mathcal{S}_i:\\ \\mathrm{rank}(j)\\neq r\\}\\right|\\cdot B_{\\text{tile}}$$</div>\n<p>其中 $B_{\\text{tile}}$ 是 K 维 tile 大小。稀疏度越高，远端命中越少，通信越省；但若 halo 圈过大，本地候选膨胀，排序开销上升。并行拓扑的调优点就是 halo 宽度与 tile 大小的乘积。</p>\n<p>具体例子：NVL72 单节点内 8 卡张量并行，序列维按帧切分，每卡负责若干帧的 Q 与全部帧的 K/V 分片。掩码复用让相邻扩散步沿用上一步的 TopK 集合，代理估计只在运动方向突变时刷新，跨 rank 交换因此呈现突发而非每步恒定，调度上需要为这种突发预留带宽余量。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-30\">三十 · 量化方案：稀疏路径与残差路径分开定精度</h3>\n<p>稀疏注意力天然把计算分成两条路径：被选中的稀疏注意力输出 $O_i$ 与稠密残差路径 $R_i$，最终 $\\tilde O_i=O_i+R_i$。这两条路径的数值敏感度不同，量化方案应分开定。稀疏路径承担主要注意力贡献，可用 FP8 甚至 NVFP4 做 QK^T 与 PV，因为被选中的 token 对本身是显著区域，量化误差被后续 softmax 归一化部分吸收；残差路径承担数值稳定职责，应保持较高精度，避免稀疏跳过的区域因残差量化误差累积而出现整体亮度漂移。</p>\n<p>量化与稀疏掩码的交互点在于能量估计本身。代理网络若用低精度推理，$e_i=\\|\\nabla_t z_i\\|$ 的排序可能在小能量差异处翻转，导致 TopK 集合抖动，进而使相邻步掩码复用失效。工程做法是代理估计保持在 FP8 以上精度，或对能量做分块最大值池化后再排序，用池化平滑低精度噪声。这一步的代价是额外的一次池化读写，显存带宽开销正比于潜变量大小，但相比重新估计全量能量的开销可以忽略。</p>\n<p>表格给出两条路径的精度分配思路：</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>精度取向</th><th>主要风险</th><th>系统代价</th></tr></thead><tbody><tr><td>稀疏 QK^T / PV</td><td>FP8 或 NVFP4</td><td>显著区域边缘量化噪声</td><td>MMA 吞吐上升，tile 对齐要求更严</td></tr><tr><td>稠密残差 $R_i$</td><td>FP8 及以上</td><td>跳过区域亮度漂移</td><td>残差路径带宽占用不随稀疏度下降</td></tr><tr><td>代理能量估计</td><td>FP8 以上或池化平滑</td><td>TopK 集合抖动、掩码复用失效</td><td>额外池化读写，带宽正比于潜变量</td></tr></tbody></table>\n<p>需要强调的是，残差路径的带宽不随稀疏度下降，这是稀疏注意力在显存带宽上的固定底噪。稀疏度提升带来的算力节省会被残差路径的读写部分抵消，因此量化方案的目标不是把残差也压到最低精度，而是让残差路径的带宽占比在总时延中保持可接受比例。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-31\">三十一 · KV 策略：QKV 缓存随帧数与分辨率增长</h3>\n<p>稀疏注意力所需的 KV 策略与缓存级复用不同：它不压缩历史 KV，而是决定哪些 KV 块需要被物化、哪些可以被跳过而不写入。长视频扩散推理中，QKV 缓存随帧数与分辨率增长，显存占用是硬约束。稀疏掩码给出一个天然的物化判据：若某 K 块在整个扩散步内从未被任何 Q 的 TopK 集合命中，则该块无需驻留，可在写入时直接丢弃或延迟物化。</p>\n<p>这一策略的收益是显存占用下降，代价是掩码估计必须先于 KV 写入完成，形成“先估能量、再定物化”的顺序依赖。工程上可把能量估计放在潜变量下采样阶段，与 VAE 解码或分块重叠解码的流水并行，使代理估计的时延被上游计算掩盖。掩码按帧间运动连续性在相邻步复用时，未被命中的 K 块可以跨步保持不物化状态，进一步摊薄估计开销。</p>\n<p>KV 策略的失败模式是运动方向突变：若掩码未及时刷新，稀疏注意力持续跳过新显著区域，画面局部停滞。防御手段是设置能量变化率的刷新触发器——当某区域能量相对上一步的增幅超过阈值时，强制该区域进入 TopK 候选并物化其 K 块。触发器的判定本身是逐 token 的轻量比较，带宽开销正比于能量向量大小，远小于重新估计全量能量。</p>\n<p>具体例子：固定分辨率长视频生成、批大小按显存档位取 1–4 的请求形态下，KV 物化策略把显存占用从全量帧对的 QKV 降为被命中 K 块加残差路径所需的部分，使单卡档位能容纳更长帧数；但残差路径与代理估计的固定开销意味着显存下降不是线性的，稀疏度翻倍不等于显存减半。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-32\">三十二 · 调度参数：稀疏度阈值与掩码复用窗口</h3>\n<p>调度参数里最关键的三个是稀疏度阈值（等价于 TopK 的 k）、掩码复用窗口长度、以及代理估计的刷新触发条件。三者互相牵制：k 越小稀疏度越高、算力越省，但漏检快速运动与遮挡区域的概率上升，表现为运动物体边缘模糊或遮挡处纹理跳变；复用窗口越长，代理估计开销越被摊薄，但运动突变时掩码滞后越严重；刷新触发越灵敏，掩码越准，但估计开销回升。</p>\n<p>调度应以 SLO 为端到端时延为主来定参：先固定复用窗口，使代理估计开销在总时延中占比降到可接受水平；再调 k，使 MMA 时间与掩码构造时间之比最大化；最后用刷新触发器兜住质量下限。这个顺序的原因是复用窗口影响的是固定开销，k 影响的是可变开销，先压固定开销再压可变开销，调参路径更短。</p>\n<p>批调度层面，稀疏注意力的批内不同请求可能处于不同扩散步，掩码复用窗口按请求独立维护，不能跨请求共享掩码。连续批处理下新请求插入会打断复用链，因此调度器应尽量把处于相同扩散步区间的请求聚成一批，使掩码复用窗口在批内对齐。这一聚合策略的代价是排队时延，收益是代理估计调用次数下降。</p>\n<p>容量规划的口径是：单步时延由 MMA 时间、掩码构造时间、代理估计时间、跨 rank 交换时间、残差路径带宽时间五项构成，稀疏度只压缩第一项与第四项，其余三项是固定或半固定开销。因此容量规划不能按理论稀疏度线性外推吞吐，而应按五项分解后的实测占比做保守估计。失败模式中“实际加速比常低于理论稀疏度”正是这五项分解的直接后果，在规则分块要求严格的档位上收益被大幅压缩。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-33\">三十三 · 可复现配置思路：从掩码对齐倒推</h3>\n<p>可复现的配置思路应当从掩码对齐倒推，而不是从硬件参数正推。第一步确定 tile 大小与 TopK 的对齐关系：令 k 为 tile 大小的整数倍，使每个被选中的 tile 完整发射 MMA，避免半 tile 掩码造成的利用率损失。第二步确定并行拓扑的切分维度：头维优先切分，序列维按 tile 边界切分并保留 halo，使跨 rank 稀疏对可在本地判定。第三步确定量化分配：稀疏路径用 FP8 或 NVFP4，残差路径保持 FP8 以上，代理估计用池化平滑。第四步确定 KV 物化判据与刷新触发器。第五步确定调度参数：复用窗口、k、批内扩散步聚合。</p>\n<p>这套配置的可复现性来自每一步都有明确的判定量：tile 对齐看 MMA 利用率，切分看跨 rank 交换占比，量化看残差路径带宽占比，KV 看显存占用与刷新触发频次，调度看五项时延分解。任一判定量偏离预期，就回到对应步骤调整，而不是全局重调。</p>\n<p>工程判断上，动态稀疏时空注意力的部署收益上限由残差路径与代理估计的固定开销封顶，稀疏度只是逼近这个上限的手段。在规则分块要求严格的 Blackwell 档位上，把 k 对齐到 tile 边界、把掩码复用窗口与批内扩散步聚合对齐，比单纯追求更高稀疏度更能兑现时延收益；而显著性估计漏检快速运动或遮挡区域的风险，最终要靠刷新触发器而非更小的 k 来兜住。</p>\n<h3 id=\"alg-sparse-dyn-attn-sec-34\">三十四 · 稀疏掩码与张量核心分块的对撞：理论加速比在哪里蒸发</h3>\n<p>动态稀疏时空注意力的代价结构，第一层不在算法本身，而在掩码与硬件执行单元之间的错配。Blackwell 的 tcgen05 MMA 以规则分块（如 128×128、64×N 的 K 维切片）驱动张量核心，一个 MMA 指令的吞吐取决于参与运算的 tile 是否被完整填满。而本算法的掩码 $M_{ij}=\\mathbb{1}[i\\in\\mathrm{TopK}(e)\\ \\text{且}\\ j\\in\\mathrm{TopK}(e)]$ 是按 token 能量排序选出的不规则集合，TopK 结果在 token 索引空间上呈碎片化分布。落到 SM 上，一个 warpgroup 拿到的稀疏 token 对往往无法凑成完整的 MMA tile，只能退化为部分填充或拆成多个小 tile 发射，张量核心的利用率随之下降。</p>\n<p>理论 FLOPs 的下降是线性的：$\\text{FLOPs}\\propto\\sum_{i}|\\mathcal{S}_{i}|$，稀疏度 $\\text{sparsity}=1-\\frac{\\sum_i|\\mathcal{S}_i|}{N^2}$ 每提高一档，乘加次数按比例减少。但实际墙钟时延取决于有效 tile 数与发射开销之比。设分块粒度为 $B$，掩码在块内的填充率为 $\\rho\\in(0,1]$，则实际加速比近似为 $\\frac{1}{\\text{sparsity}}\\cdot\\rho$ 的倒数关系——当 $\\rho$ 因碎片化跌到低位时，即便稀疏度很高，端到端时延也只小幅改善。这就是材料中“实际加速比常低于理论稀疏度”的机制根源，且“在规则分块要求严格的档位上收益被大幅压缩”。工程上的应对不是改掩码语义，而是把 TopK 选择约束到块对齐的候选集上：先按 $B$ 粒度的块能量排序，再在块内做 token 级精选，使每个被激活的 tile 尽量填满，用少量稀疏度损失换回张量核心利用率。</p>\n<p>具体例子：一段 1080p、数十帧的长视频，潜变量序列长度达到数万 token，注意力头维度 128。若 TopK 选出的显著 token 在索引上均匀散落，单个 128×128 tile 可能只命中十几个有效 token 对，MMA 仍要按整 tile 计时，等效算力浪费接近一个数量级；而改成块对齐候选后，同样稀疏度下有效 tile 数下降，SM 的 MMA 发射次数同步下降，时延才真正跟随 FLOPs 走。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-35\">三十五 · 显存与带宽：QKV 缓存随帧数分辨率线性膨胀</h3>\n<p>稀疏化只削减了 $QK^{\\top}$ 与 $PV$ 的乘加，并没有削减 QKV 本身的驻留。材料明确指出“KV 即稀疏注意力所需的 QKV 缓存”，“显存占用随帧数与分辨率增长”。这是本算法在规模上最先撞到的墙之一：注意力 FLOPs 可以随稀疏度线性下降，但 QKV 张量的字节数正比于 token 数乘以头数乘以维度乘以精度字节，与稀疏度无关。长视频高分辨率下，token 数按帧数与空间分辨率的乘积增长，QKV 缓存成为显存占用的主导项，而非权重。</p>\n<p>带宽侧同样如此。稀疏跳过减少的是从 shared memory / TMEM 到 MMA 的读取次数，但显著性估计阶段仍要读一遍潜变量或光流代理输入；掩码复用虽摊薄了估计开销，却改变不了每步至少一次的全量 QKV 写入与残差路径读取。设单步注意力数据量为 $D_{\\text{qkv}}+D_{\\text{res}}$，稀疏化把 $D_{\\text{qkv}}$ 的读取压缩到 $1-\\text{sparsity}$ 量级，但 $D_{\\text{res}}$ 的稠密残差路径 $R_i$ 是全量读写的——这是维持数值稳定的必要代价，也是带宽账上一笔无法稀疏掉的固定支出。在 HBM 带宽成为瓶颈的档位上，稀疏注意力的收益会被残差路径的稠密流量稀释。</p>\n<p>工程判断：显存规划要按“稠密 QKV + 稀疏中间结果”而非“稀疏 QKV”估算。批大小按显存档位取 1–4 的配方正是这一约束的体现——批再大，QKV 缓存先爆，而不是算力先爆。分块重叠、KV 量化等手段属于其他条目的主题，此处只需记住：本算法自身不解决 QKV 驻留，规模上限由帧数与分辨率带来的显存与带宽约束决定。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-36\">三十六 · 代理估计的固定开销与掩码复用的摊薄边界</h3>\n<p>显著性估计是本算法的前置成本：下采样潜变量或用轻量代理网络估计每 token 的运动能量 $e_i=\\|\\nabla_t z_i\\|$。这笔开销与稀疏度无关，是每步（或每次掩码刷新）的固定支出。掩码按帧间运动连续性在相邻步复用，正是为了把这笔固定成本摊到多个去噪步上——设复用窗口为 $W$ 步，则单步摊销的估计成本约为 $\\frac{C_{\\text{est}}}{W}$，$W$ 越大摊得越薄。</p>\n<p>但复用有边界，且这个边界是尾延迟的来源。材料给出的失败模式很具体：“掩码按帧间运动连续性在相邻步复用时，若运动方向突变而掩码未及时刷新，稀疏注意力会持续跳过新显著区域，造成画面局部停滞。”换句话说，$W$ 的选择是一个延迟—质量的权衡：$W$ 大则摊销好、吞吐高，但运动突变时掩码滞后，新显著区域被系统性跳过；$W$ 小则响应快，但代理估计开销重新抬头，稀释稀疏带来的时延收益。工程上通常用运动能量的帧间差分做刷新触发器——当 $\\|\\Delta e\\|$ 超过阈值时强制重算掩码，把 $W$ 从固定值改为自适应，代价是引入一次不可预测的估计尖峰。</p>\n<p>这个尖峰直接体现为尾延迟。稳态下每步时延由稀疏 MMA 主导，分布较窄；一旦触发掩码刷新，该步要额外跑一次代理网络与 TopK 排序，时延抬升。在 SLO 以端到端时延为主的负载配方下，P99 而非均值才是容量规划的锚点。若刷新频率随视频运动剧烈程度上升，尾延迟会随内容而漂移，容量规划必须按最坏运动场景留余量，而不是按平均稀疏度算吞吐。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-37\">三十七 · 通信：稀疏掩码在张量并行下的跨卡不一致</h3>\n<p>部署配方以单卡或单节点张量并行为主，这决定了通信账的形态。张量并行把注意力头或序列维切到多卡，每卡独立计算自己那份 $QK^{\\top}$ 与 $PV$。问题在于 TopK 是在全局 token 能量排序上做的：若各卡只按本地分片的能量选 TopK，选出的显著集合在卡间不一致，拼起来的注意力输出会缺失跨片的显著 token 对；若先做全局排序再分发掩码，则每步都要一次跨卡的能量归约（all-reduce 或 all-gather），这笔通信量与 token 数成正比，且发生在注意力计算之前的关键路径上。</p>\n<p>掩码复用在通信侧是双刃剑：复用窗口内掩码不变，跨卡归约可以省掉；但一旦刷新，归约与掩码分发同时发生，形成一次通信尖峰。NVLink 5 与 NCCL 能把单节点内的这次归约压到较低时延，但它仍是串行于计算之前的同步点。规模上去后，若拓扑跨到多节点，掩码分发的 all-gather 走跨节点链路，其带宽远低于节点内，这次尖峰会从“可忽略”变成“尾延迟主因”。因此本算法的并行拓扑宜停留在单节点张量并行，跨节点扩展应优先考虑把稀疏注意力限制在节点内、节点间走其他维度的切分，避免让掩码同步成为跨节点通信的常客。</p>\n<p>具体代价形态：一次掩码刷新的跨卡归约数据量为 token 数乘以能量标量字节数，量不大但时延敏感；它不占带宽大头，却卡在关键路径上，属于典型的“小消息、高同步”开销。工程上可用异步预取把下一窗口的掩码估计提前到当前步的计算阴影里，用计算掩盖这次通信。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-38\">三十八 · 功耗与规模崩塌的先后次序</h3>\n<p>稀疏注意力的功耗账与算力账并不同步。张量核心在部分填充 tile 上仍按整 tile 的时钟周期运行，功耗不随有效 token 对线性下降；显著性估计的代理网络是稠密小算子，功耗密度不低；稠密残差路径 $R_i$ 的读写持续占用 HBM 控制器。三者叠加，使得“FLOPs 降了、功耗没怎么降”成为常见现象。在功耗封顶的机柜（如 NVL72 这类高密度整机柜）里，稀疏化带来的能效改善会被这些固定功耗项摊薄，真正决定每瓦吞吐的是有效 tile 占比而非名义稀疏度。</p>\n<p>规模上去以后，崩塌的次序可以按约束的刚性排序。显存最先：QKV 缓存随帧数与分辨率线性增长，与稀疏度无关，批大小 1–4 的档位很快触顶。其次是尾延迟：掩码刷新与跨卡归约的尖峰随运动剧烈程度和并行度放大，P99 先于均值恶化。再次是有效算力：碎片化使实际加速比低于理论值，规模越大、分块约束越严，这个折扣越狠。带宽与功耗排在后面，因为它们更多是稀释收益而非直接触发失败。这个次序意味着容量规划应先按显存定帧数上限，再按最坏运动场景定刷新策略与并行拓扑，最后才用稀疏度去谈吞吐收益。</p>\n<p>失败模式的叠加也值得注意：显著性估计漏检快速运动或遮挡区域，导致“运动物体边缘模糊或遮挡处纹理跳变”；若此时掩码又因复用未刷新而持续跳过新显著区域，两种失效会共振——既漏检又滞后，画面局部停滞与纹理跳变同时出现。这类质量退化在稀疏度推高时更易触发，因为 TopK 集合变小，漏检的边际代价变大。工程判断是：稀疏度的上限不该由 FLOPs 收益单独决定，而应由“最坏运动场景下漏检率可接受”反推，把稀疏度留出余量给运动突变。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-39\">三十九 · 把系统代价折进掩码设计：一个可操作的判断</h3>\n<p>把上述代价折进掩码设计，核心是把“选哪些 token”从纯能量排序改为带系统约束的排序。伪代码思路：先按 $B$ 粒度的块能量排序得块级候选，再在候选块内按 token 能量精选，使激活 tile 填充率 $\\rho$ 不低于阈值；同时把掩码刷新触发器绑定到帧间能量差分 $\\|\\Delta e\\|$，超过阈值即重算并同步跨卡；残差路径 $R_i$ 保持稠密不稀疏。这样做的代价是牺牲一点名义稀疏度换回张量核心利用率与尾延迟可控性。</p>\n<div class=\"formula\">$$\\text{有效加速}\\approx\\frac{1}{1-\\text{sparsity}}\\cdot\\rho\\cdot\\frac{W}{W+\\tau_{\\text{refresh}}/T_{\\text{step}}}$$</div>\n<p>式中 $\\rho$ 是 tile 填充率，$\\tau_{\\text{refresh}}$ 是单次掩码刷新的额外时延，$T_{\\text{step}}$ 是稳态单步时延，$W$ 是复用窗口。三项分别对应分块错配、刷新尖峰与摊销收益——任何一项接近零，整体加速就归零。这个式子不是精确模型，而是把本部分讲的四类代价（分块、显存带宽、通信同步、尾延迟）压进一个可比较的结构里，让工程判断落在“先保 $\\rho$ 与刷新可控，再谈稀疏度”上。</p>\n<p>具体到部署：单节点张量并行、批大小按显存档位取 1–4、量化配合 FP8/NVFP4、掩码自适应刷新——这套组合的吞吐上限由显存与 P99 共同钉死，而不是由理论 FLOPs 下降曲线决定。规模再往上，先崩的是 QKV 驻留与掩码同步，而不是张量核心算力；把稀疏度当吞吐杠杆之前，先把这两项的系统代价算清楚。</p>\n<h3 id=\"alg-sparse-dyn-attn-sec-40\">四十 · 精度塌陷：残差路径掩盖的数值病</h3>\n<p>稀疏时空注意力的数值风险不在稀疏本身，而在“稀疏输出 + 稠密残差”这条组合路径。$\\tilde O_i=O_i+R_i$ 的设计初衷是保稳定，但它同时制造了一个诊断盲区：当 $O_i$ 因掩码漏检而退化时，残差 $R_i$ 会把输出拉回一个“看起来正常”的量级，端到端 loss 与画面整体亮度都不报警，只有运动区域边缘出现纹理跳变。工程上要把 $O_i$ 与 $R_i$ 的贡献比例单独打点，按 token 统计 $\\|O_i\\|/\\|\\tilde O_i\\|$，该比值在显著 token 上应稳定在较高区间；一旦某帧该比值骤降，说明 TopK 选出的 token 与真实运动区域错位，稀疏分支实际在“空转”。配合 FP8/NVFP4 量化时，稀疏分支的 QK^T 只覆盖掩码内 token 对，其数值分布比全注意力更窄，per-tensor 缩放因子容易被残差路径的大值主导，导致稀疏分支的有效位宽被压缩——这是精度塌陷的第二个来源。诊断手段是对 $O_i$ 单独做 per-block 量化误差统计，而不是对 $\\tilde O_i$ 统计。</p>\n<div class=\"formula\">$$\\text{ratio}_i=\\frac{\\|O_i\\|_2}{\\|O_i+R_i\\|_2},\\quad \\text{flag}=\\mathbb{1}[\\text{ratio}_i&lt;\\tau]\\ \\text{且}\\ e_i\\in\\mathrm{TopK}(e)$$</div>\n<p>代价上，这套逐 token 范数统计若在每步都做，会引入额外的 reduce 与同步，在单卡批大小 1–4 的长视频请求里直接吃掉个位数百分比端到端时延；可行做法是只对稀疏掩码命中的 token 采样统计，按帧间隔抽样而非逐步全量。具体例子：一段含快速横移镜头的长视频，前若干步掩码按运动连续性复用，物体已移出原 TopK 集合，$O_i$ 在新位置近乎为零而 $R_i$ 仍带旧位置特征，ratio 指标在位移帧上出现尖刺，而画面整体 PSNR 几乎不变——这正是必须靠分支级指标而非端到端指标才能抓到的失败。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-41\">四十一 · 显存与 OOM：稀疏不等于省显存</h3>\n<p>稀疏注意力降低的是 FLOPs，不是显存。QKV 缓存仍按全 token 分配，掩码本身若以稠密布尔矩阵存储，规模是 $N^2$ 位图，在长视频高分辨率下会与 KV 缓存同量级甚至更大；若用 CSR/位压缩表示，又要付出索引构造与 gather 的带宽代价。OOM 的典型触发点不是注意力计算瞬间，而是三步叠加：帧数与分辨率增长带来的 KV 线性增长、掩码复用需要保留相邻步掩码副本、以及代理网络（下采样潜变量或轻量光流估计）的中间激活。诊断上应把显存拆成四本账——KV 缓存、掩码存储、代理网络激活、残差路径中间量——分别打点峰值，而不是只看整体 reserved。</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{mask}}\\approx\\frac{N^2}{8}\\ \\text{B（位图）}\\quad\\text{vs}\\quad \\text{Mem}_{\\text{KV}}\\propto N\\cdot d\\cdot L\\cdot \\text{bytes}$$</div>\n<p>工程判断：当 $N$ 增大到掩码位图与 KV 同量级时，稀疏化的显存收益转为负值，此时必须改用块级稀疏（以 token 块为最小单位建掩码）而非 token 级位图，把掩码存储降到 $(N/B)^2$。代价是块级掩码的粒度变粗，稀疏度上限被块大小锁死，实际加速比进一步偏离理论值。具体例子：批大小取到显存档位上限时，代理网络若与主模型同卡常驻，其激活峰值会与 KV 峰值在时间上错开却共享同一显存池，OOM 往往发生在代理估计步而非注意力步——监控要按步类型分桶统计峰值，才能定位是哪一个子系统把水位推过线。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-42\">四十二 · 批抖动与路由不均：稀疏度的方差问题</h3>\n<p>连续批处理下，动态稀疏的致命处在于每个请求、每一帧的稀疏度不同，导致同一 batch 内不同序列的计算量不可预测。调度器按 token 数或按固定 FLOPs 估算配额时，遇到运动剧烈的样本（TopK 集合大、掩码命中率高）就会出现单步时延被单个样本拖长，形成批抖动。更隐蔽的是路由不均：TopK 按能量排序选 token，能量分布长尾，少数高能量 token 被反复选中，其所在 SM 或 warp 的负载显著高于其他；在 2-SM MMA 与 tcgen05 路径上，这种不均表现为部分 tensor core 空转、部分排队，整体吞吐由最慢的分块决定。</p>\n<div class=\"formula\">$$\\text{imbalance}=\\frac{\\max_k |\\mathcal{S}^{(k)}|}{\\frac{1}{K}\\sum_k |\\mathcal{S}^{(k)}|},\\quad \\text{jitter}=\\frac{p99(\\text{step latency})}{p50(\\text{step latency})}$$</div>\n<p>诊断要点是把稀疏度按请求维度打分布，而不是打均值：均值稳定而 p99 漂移，就是批抖动的信号。缓解手段包括按稀疏度分桶路由请求（把高能量样本聚到同批，避免与低能量样本互相拖累）、对 TopK 集合做容量上限截断（牺牲少量显著 token 换取分块规整）、以及在掩码构造阶段做块对齐填充，把不规则命中整理成规则块以恢复 tensor core 利用率。代价是截断与填充都引入额外计算，稀疏度的理论收益被折损；分桶路由则增加排队时延，与端到端 SLO 冲突，需要按 SLO 类型取舍。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-43\">四十三 · 尾延迟尖刺：掩码刷新与运动突变</h3>\n<p>尾延迟尖刺有三个可辨识的来源。其一是掩码刷新步：按帧间运动连续性复用掩码能摊薄代理估计开销，但刷新那一帧要重跑代理网络并重建 TopK，计算量突增，形成周期性尖刺；尖刺周期与复用步数同频，监控上表现为延迟序列的等间隔峰。其二是运动方向突变：复用掩码未及时刷新时，稀疏分支持续跳过新显著区域，画面局部停滞，此时计算量反而下降，延迟变好但质量崩坏——这是“延迟指标向好而质量指标恶化”的反常组合，必须把质量代理指标（如相邻帧运动区域的光流残差）与延迟同图对照。其三是遮挡区域的显著性漏检，代理网络在遮挡处能量估计偏低，TopK 漏选，后续帧因连续性复用继续漏选，误差沿时间累积。</p>\n<div class=\"formula\">$$\\text{refresh}=\\mathbb{1}\\big[\\ \\|\\nabla_t z\\|_{\\text{frame}}&gt;\\theta\\ \\ \\text{或}\\ \\ \\text{step}\\bmod T_{\\text{reuse}}=0\\ \\big]$$</div>\n<p>工程上把刷新判据从固定周期改为运动能量触发，可在运动突变帧提前刷新、在静止段延长复用，代价是每帧多一次能量统计的轻量 reduce。具体例子：镜头切换帧上，光流代理的能量估计整体跳变，若仍按固定周期复用，切换后的若干帧全部落在旧掩码上，表现为切换处纹理错位与闪烁；把切换检测并入刷新判据后，尖刺从周期性变为事件驱动，p99 延迟的可预测性显著提升。监控上应为刷新步单独建延迟桶，避免其污染常规步的 p50 统计。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-44\">四十四 · 监控面与回滚：把稀疏当可降级特性</h3>\n<p>监控面要覆盖四层：算子层（稀疏分支与残差分支的范数比、掩码命中率、块对齐填充比例）、显存层（KV/掩码/代理/残差四本账峰值）、调度层（按请求的稀疏度分布、批内计算量方差、分桶排队时长）、质量层（运动区域光流残差、遮挡处纹理跳变的帧间差分）。四层指标必须能按同一 request id 关联，否则无法判断一次尾延迟尖刺是掩码刷新还是显存水位导致的降频。告警阈值应设在稀疏度分布的 p99 与范数比的下尾，而不是均值。</p>\n<ul>\n<li>回滚路径一：掩码降级为块级稀疏并强制块对齐，牺牲稀疏度上限换 tensor core 规整性，适用于加速比低于预期的档位。</li>\n<li>回滚路径二：关闭掩码复用，逐步重估代理，用计算量换质量，适用于运动突变与遮挡漏检引发的闪烁。</li>\n<li>回滚路径三：稀疏分支整体旁路，退化为稠密注意力加残差，作为 OOM 与精度塌陷的兜底，代价是时延回到全注意力水平。</li>\n<li>回滚路径四：降低批大小或改分桶路由，缓解批抖动，代价是吞吐下降与排队时延上升。</li>\n</ul>\n<p>回滚必须是运行时可切换的开关而非重启配置，因为失败模式多在长视频后段才显现，重启会丢掉已生成的 KV 与掩码状态。判断准则落在一条具体机制上：当 $\\text{ratio}_i$ 的下尾与稀疏度 p99 同时越界，说明稀疏分支已在空转且负载不均，此时先切块对齐再考虑旁路；若只有延迟尖刺而 ratio 正常，则优先改刷新判据而非动稀疏度。把稀疏注意力当作可降级特性来运维，而不是当作固定优化来部署，是这套算法在 Blackwell 上稳定落地的分界线。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-45\">四十五 · 当稀疏掩码撞上张量核心：四类失效与可回滚的监控面</h3>\n<p>动态稀疏时空注意力的失效几乎都发生在“掩码”这一层：它既是加速的来源，也是精度与调度抖动的来源。第一类是分块失配。Blackwell 的 tcgen05 MMA 与 2-SM 协作对 K 维与 M/N 分块有硬性对齐要求，掩码若按 token 粒度随机置零，稀疏的 QK^T 会被迫退化为“带零块”的稠密计算，理论 FLOPs 按 <span class=\"formula\">$$\\text{FLOPs}\\propto\\sum_{i}|\\mathcal{S}_{i}|$$</span> 线性下降，但实际 SM 占用率由最大非零块决定，加速比被压缩。工程上应把 top-k 选择约束到 64/128 token 的块粒度上，让掩码在块级呈连续区间，再用块稀疏的 CUTLASS/TensorRT-LLM 内核承接；代价是块粒度越粗，稀疏度上限越低，长视频高分辨率下可用的有效稀疏度被块大小封顶。诊断信号是“名义稀疏度”与“实测 MMA 利用率”的比值，二者长期背离即说明掩码与分块不匹配。</p>\n<p>第二类是显著性漏检。代理能量 <span class=\"formula\">$$e_i=\\|\\nabla_t z_i\\|$$</span> 对慢速平移稳健，却对快速运动、遮挡切换与镜头切换不敏感：能量排序把新进入画面的区域排在 top-k 之外，<span class=\"formula\">$$M_{ij}=\\mathbb{1}[i\\in\\mathrm{TopK}(e)\\ \\text{且}\\ j\\in\\mathrm{TopK}(e)]$$</span> 直接把这些 token 对跳过，输出只剩稠密残差 <span class=\"formula\">$$\\tilde O_i=O_i+R_i$$</span> 的捷径分量，表现为运动物体边缘模糊、遮挡处纹理跳变与逐帧闪烁。监控应盯住“被跳过 token 的残差占比”与帧间光流的突变检测：当某帧光流幅值分布相对前一帧显著右移而 top-k 集合几乎不变时，说明掩码未刷新，需强制重估。代价是重估频率上升会吃掉掩码复用摊薄掉的代理开销，端到端时延随之抬升。</p>\n<p>第三类是掩码复用导致的局部停滞。按帧间运动连续性在相邻扩散步复用掩码，本意是摊薄代理估计，但运动方向突变时旧掩码持续跳过新显著区域，画面局部静止。这本质是“掩码年龄”问题：应给掩码设 TTL，按光流方向变化率触发刷新，而非固定步数复用。第四类是批抖动与尾延迟尖刺：批大小按显存档位取 1–4，稀疏注意力的 QKV 缓存随帧数与分辨率增长，不同请求的稀疏度不同，导致同一 batch 内 kernel 时长离散，连续批处理下尾请求被长请求拖住。容量规划应把稀疏度作为调度维度，按实测稀疏度分桶而非按请求数分桶，并对稀疏度异常低的请求单独成批。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>系统代价</th><th>回滚动作</th></tr></thead><tbody><tr><td>分块失配</td><td>名义/实测稀疏度比值偏离</td><td>加速比低于理论值，SM 空转</td><td>切回稠密内核或调粗块粒度</td></tr><tr><td>显著性漏检</td><td>跳过 token 残差占比升高、光流突变</td><td>细节丢失与闪烁，需重估增时延</td><td>强制刷新掩码、临时降稀疏度</td></tr><tr><td>掩码复用停滞</td><td>top-k 集合长期不变而光流已变</td><td>局部画面停滞</td><td>缩短 TTL、按方向变化率刷新</td></tr><tr><td>批抖动/尾尖刺</td><td>batch 内 kernel 时长离散度</td><td>尾延迟抬升，SLO 违约</td><td>按稀疏度分桶、隔离异常请求</td></tr></tbody></table>\n<p>回滚必须分级：精度类问题（漏检、停滞）先降稀疏度而非关稀疏，因为稠密残差路径已保证数值稳定，降稀疏度只是把 top-k 扩大，画面连续性恢复最快；性能类问题（分块失配、尾尖刺）则切回稠密注意力内核或改调度分桶，代价是时延回到全注意力水平。两条路径都要求掩码与稀疏度作为可热更新的运行时参数暴露给服务层，而不是编译期常量——这是该方案能否在 GB200 NVL72 这类多卡拓扑上稳定跑长视频请求的前提。</p>\n<h3 id=\"alg-sparse-dyn-attn-sec-46\">四十六 · 对照维度：稀疏发生在哪一层</h3>\n<p>选型的第一刀不是切在“哪个算法更快”，而是切在“稀疏发生在哪一层”。同族算法看着都在省注意力算力，实际作用点分三类：算子级稀疏（本条目）、缓存级复用（轨迹感知缓存复用与校正）、精度级压缩（精度分配稀疏时空注意力）。三者的代价结构完全不同——算子级稀疏省的是 QK^T 与 PV 的乘加，缓存级复用省的是整块前向重算，精度级压缩省的是权重与激活的位宽。一个请求如果瓶颈在注意力 FLOPs 占比高（长帧数、高分辨率、潜变量 token 多），算子级稀疏是主武器；如果瓶颈在去噪步之间的重复计算，缓存级复用收益更大；如果瓶颈在显存带宽与权重搬运，精度级压缩才是对症的。把这三者混为一谈，就会出现“稀疏度拉到 0.8 却只换来 1.3 倍加速”的错配，因为掩码破坏规则分块后，张量核心的有效利用率塌了下来。</p>\n<p>本条目与固定稀疏模式的差别也必须在这一层说清：局部窗口或固定步长稀疏是按位置选掩码，代价可预测、分块友好，但对运动区域的跟随是盲的；本条目按运动能量 $e_i=\\|\\nabla_t z_i\\|$ 动态选 top-k，掩码随内容走，代价是掩码不规则且需要代理估计。选型时先问一句：这个负载的运动区域是否真的稀疏且可估？如果镜头整体运动、token 能量分布平坦，动态选 top-k 退化成近似全选，代理估计的开销纯属白付。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-47\">四十七 · 决策表：四类负载的落点</h3>\n<p>下表把可用事实里的适用条件压成可执行的判断，列的是“首选算法”与“必须接受的代价”，不是性能排名。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>负载特征</th><th>首选</th><th>次选</th><th>必须接受的代价</th></tr>\n</thead>\n<tbody>\n<tr><td>长视频、高分辨率、运动区域稀疏、SLO 以端到端时延为主</td><td>动态稀疏时空注意力（本条目）</td><td>固定稀疏模式作为兜底</td><td>掩码破坏规则分块，实际加速比低于理论稀疏度</td></tr>\n<tr><td>去噪步间轨迹高度相关、单步算力不是瓶颈</td><td>轨迹感知缓存复用与校正</td><td>本条目作二级加速</td><td>缓存失效时的重算抖动</td></tr>\n<tr><td>显存带宽受限、权重搬运占比高</td><td>精度分配稀疏时空注意力</td><td>FP8/NVFP4 量化路径</td><td>低位宽下的数值稳定性与精度分配开销</td></tr>\n<tr><td>运动剧烈、遮挡频繁、细节敏感</td><td>全注意力或固定局部窗口</td><td>本条目配稠密残差与掩码强制刷新</td><td>放弃稀疏收益，换画面稳定</td></tr>\n</tbody>\n</table>\n<p>这张表的读法是“先排除，再优选”。第一行是本条目的正命区：材料明确它面向固定分辨率长视频生成、批大小按显存档位取 1–4、SLO 以端到端时延为主，且注意力 FLOPs 随稀疏度线性下降。第四行是它的禁区：显著性估计漏检快速运动或遮挡区域会导致局部细节丢失与闪烁，表现为运动物体边缘模糊或遮挡处纹理跳变——这类负载上，稀疏省下的时延会被画质返工吃掉。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-48\">四十八 · 与缓存级复用的组合判据</h3>\n<p>本条目与轨迹感知缓存复用不是替代关系，而是两级漏斗。缓存级复用决定“这一步要不要算”，算子级稀疏决定“要算的那一步里算多少 token 对”。组合的判据是一个简单的乘性收益估计：设缓存命中率为 $h$，稀疏度为 $s$，则端到端注意力开销近似正比于 $(1-h)\\cdot(1-s)\\cdot C_{\\text{dense}}$，其中 $C_{\\text{dense}}$ 是全注意力的单步代价。这个式子只在两级加速互不干扰时成立——实际上掩码复用与缓存复用共享同一个“帧间运动连续性”假设，一旦运动方向突变，两级同时失效，误差会叠加而非抵消。</p>\n<div class=\"formula\">$$\\text{Cost}_{\\text{combo}}\\approx(1-h)\\,(1-s)\\,C_{\\text{dense}}+\\lambda\\,C_{\\text{proxy}}$$</div>\n<p>$\\lambda C_{\\text{proxy}}$ 是代理估计的摊薄开销：掩码按帧间运动连续性在相邻步复用，代理估计被摊薄，但摊薄的前提是复用命中。工程判断是：当 $h$ 已经很高（缓存扛住了大部分步），再叠算子级稀疏的边际收益被 $\\lambda C_{\\text{proxy}}$ 侵蚀，此时应把稀疏度调低、把预算留给画质；当 $h$ 低而 $s$ 可高（长视频、镜头运动平缓），本条目应作为主加速，缓存复用退为辅助。两级都开时，掩码刷新周期必须与缓存失效周期对齐，否则会出现“缓存重算了整块、稀疏掩码却还在跳过新显著区域”的局部停滞。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-49\">四十九 · 与精度级稀疏的分工</h3>\n<p>精度分配稀疏时空注意力与本条目的分工在“省什么”上：前者省位宽与带宽，后者省乘加次数。二者可以叠加，但叠加顺序影响数值稳定性。本条目靠稀疏结果与稠密残差路径相加得 $\\tilde O_i=O_i+R_i$ 来维持稳定，如果残差路径本身已被量化到 FP8/NVFP4，残差里的小量级修正会被低位宽吞掉，稀疏跳过的区域就失去了稠密路径的兜底。因此工程上的顺序是：先定精度档位，再定稀疏度——低位宽档位上把稀疏度压低，让残差路径有足够的动态范围承载被跳过 token 的贡献。</p>\n<p>代价侧要算清一笔账：稀疏省下的是计算时间，量化省下的是显存与带宽。在 Blackwell 上，若瓶颈是显存容量（帧数与分辨率带来的 QKV 缓存增长），量化是主解，稀疏只是顺带；若瓶颈是端到端时延且算力打满，稀疏是主解。材料给出的部署配方是单卡或单节点张量并行、量化可配合 FP8/NVFP4、显存占用随帧数与分辨率增长——这意味着在长视频高分辨率档位上，两者往往必须同时开，而同时开的代价就是上面说的残差动态范围收窄。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-50\">五十 · 适用条件的硬边界与规模上限</h3>\n<p>三条硬边界决定本条目能不能上。第一条是分块友好度：稀疏掩码破坏张量核心的规则分块，实际加速比常低于理论稀疏度，在规则分块要求严格的档位上收益被大幅压缩。判断方法是看 top-k 选出的 token 集合在空间上是否成簇——成簇则掩码可被重排成较规则的分块，加速比接近理论值；散乱则分块利用率低，稀疏度 0.7 可能只兑现 0.3 的时延收益。第二条是运动可估性：显著性估计漏检快速运动或遮挡区域，细节丢失与闪烁是画质问题而非性能问题，但它会让 SLO 以端到端时延为主的请求因返工而实际超时。第三条是掩码时效：掩码按帧间运动连续性复用时，若运动方向突变而掩码未及时刷新，稀疏注意力会持续跳过新显著区域，造成画面局部停滞——这条的工程对策是给掩码复用加一个能量变化触发器，能量分布漂移超过阈值就强制重估，代价是代理开销不再被完全摊薄。</p>\n<p>规模上限受帧数与分辨率带来的显存与带宽约束，材料未给出具体上限数值，因此容量规划只能定性：批大小按显存档位取 1–4，帧数上升时 QKV 缓存线性增长，稀疏本身不减少缓存占用（它只减少计算），所以长视频的显存墙先于算力墙到来。这意味着本条目在超长视频上必须与 KV 量化或分块流式方案并用，单靠稀疏无法突破显存上限。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-51\">五十一 · 选型的工程判断</h3>\n<p>把上面的判据收成一句可执行的话：先测运动能量分布的平坦度，再测掩码的成簇度，最后测残差路径的动态范围。三项都过，本条目作为主加速，稀疏度按成簇度定档、按精度档位打折；平坦度高则退回固定局部窗口，成簇度低则降低稀疏度并把预算给缓存复用，残差动态范围不足则先修量化再谈稀疏。选型不是选“最强算法”，而是选“代价结构与该请求瓶颈对齐的那一个”——本条目对齐的是注意力 FLOPs 主导的长视频高分辨率时延瓶颈，错配到显存瓶颈或画质敏感负载上，它省下的算力会被返工与停滞吃掉。</p>\n\n<h3 id=\"alg-sparse-dyn-attn-sec-52\">五十二 · 选型边界：动态稀疏掩码与相邻方案的取舍判据</h3>\n<p>把动态稀疏时空注意力放回同族算法谱系里，第一条分界线是掩码是否随内容变化。固定稀疏模式（局部窗口、固定步长扩张、块状对角）的掩码在编译期就确定，能整块对齐张量核心的 MMA tile，稀疏度直接映射为分块跳过率，工程上可预测；代价是对运动区域的覆盖靠先验，运动一旦越出窗口就整段丢失。动态 top-k 方案则把掩码交给 $e_i=\\|\\nabla_t z_i\\|$ 或代理网络输出决定，$M_{ij}=\\mathbb{1}[i\\in\\mathrm{TopK}(e)\\ \\text{且}\\ j\\in\\mathrm{TopK}(e)]$，覆盖随内容走，但掩码不规则。第二条分界线是稀疏发生在哪一层：本方案属于注意力算子级稀疏，只砍 QK^T 与 PV 的 token 对；缓存级复用（KV 淘汰、页级复用）砍的是显存与带宽，两者可叠加但收益来源不同，不能互相替代。第三条是数值路径：本方案保留稠密残差 $\\tilde O_i=O_i+R_i$，而纯稀疏近似往往直接丢弃被跳过项，长序列上层叠后容易漂移。</p>\n<p>决策时先看稀疏度的理论上限与实际可达加速之间的落差。理论 FLOPs 按 $\\text{FLOPs}\\propto\\sum_i|\\mathcal{S}_i|$ 线性下降，$\\text{sparsity}=1-\\sum_i|\\mathcal{S}_i|/N^2$；但掩码破坏规则分块后，张量核心仍按 tile 粒度发射，实际加速比常显著低于理论稀疏度。判据是：若稀疏度落在分块粒度以下（稀疏 token 散落在多数 tile 内），跳过几乎不产生时钟节省，此时应改用固定块状模式或直接全注意力；只有当显著 token 在空间上成簇、能凑成整 tile 时，动态掩码才兑现收益。下表给出同族方案的适用条件对照。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>掩码来源</th><th>加速可预测性</th><th>适用条件</th><th>主要失效点</th></tr></thead><tbody><tr><td>全注意力</td><td>无</td><td>高（基准）</td><td>短序列、运动密集、分块利用率优先</td><td>长视频算力浪费</td></tr><tr><td>固定窗口/步长稀疏</td><td>编译期先验</td><td>高</td><td>运动幅度可预估、tile 对齐要求严格</td><td>越窗运动丢失</td></tr><tr><td>动态 top-k 稀疏（本方案）</td><td>运动能量排序</td><td>低（受分块约束）</td><td>长视频高分辨率、运动区域稀疏且成簇</td><td>漏检快运动、掩码复用滞后</td></tr><tr><td>缓存级 KV 复用</td><td>历史帧缓存</td><td>中</td><td>显存/带宽受限、帧间冗余高</td><td>缓存淘汰误伤新显著区</td></tr></tbody></table>\n<p>失效条件要按系统代价来称量。显著性估计本身是一笔固定开销：下采样潜变量或轻量代理网络的耗时与帧数、分辨率同阶增长，只有靠帧间运动连续性复用掩码才能摊薄；一旦运动方向突变而掩码未及时刷新，稀疏注意力会持续跳过新显著区域，画面出现局部停滞，这比单纯漏检更难排查，因为错误在时间上自洽。漏检快速运动或遮挡区域则表现为运动物体边缘模糊、遮挡处纹理跳变。显存侧，QKV 缓存随帧数与分辨率增长，稀疏只减算力不减缓存，批大小按显存档位取 1–4 时，收益主要落在端到端时延而非吞吐。工程判断是：以端到端时延为 SLO、分辨率高且运动稀疏的长视频扩散请求，本方案优先；若档位对规则分块要求严格、或场景运动密集且快速，应退回固定块状稀疏或全注意力，并把预算投向缓存级复用与 FP8/NVFP4 量化。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 少步蒸馏与轨迹缓存复用</td></tr><tr><td>解决什么</td><td>视频时空注意力对全部帧对做全连接，实际运动区域只占少数token，全注意力在长视频上算力浪费严重。</td></tr><tr><td>一句话机制</td><td>用低分辨率或光流代理估计token运动显著性，只对显著token对保留注意力，其余走稀疏跳过。</td></tr><tr><td>代价与失效</td><td>稀疏掩码破坏张量核心的规则分块，实际加速比常低于理论稀疏度；显著性估计漏检快速运动或遮挡区域，导致局部细节丢失与闪烁</td></tr><tr><td>后继</td><td>长视频自回归2bit KV量化</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-sparse-dyn-attn · 共 8 个片段</p>\n";break;}}})();
